export default {"file":"generate-tc.html","title":"Transfer Certificate - Schoolix","htmlClass":"","bodyClass":"","body":"\r\n<div id=\"sxPageLoader\" class=\"sx-page-loader\" role=\"status\" aria-live=\"polite\">\r\n  <section class=\"dots-container\" aria-label=\"Loading page\">\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n  </section>\r\n</div>\r\n  <div class=\"toast-host\" id=\"toastHost\"></div>\r\n\r\n  <div class=\"container\">\r\n    <!-- Top bar -->\r\n    <div class=\"top-bar\">\r\n      <div class=\"brand\">\r\n        <div class=\"brand-mark\" aria-hidden=\"true\">\r\n          <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"9\" y1=\"15\" x2=\"15\" y2=\"15\"/><line x1=\"9\" y1=\"11\" x2=\"15\" y2=\"11\"/></svg>\r\n        </div>\r\n        <div>\r\n          <h1>Transfer Certificate</h1>\r\n          <div class=\"subtitle\">Issue official TC, print, and manage records</div>\r\n        </div>\r\n      </div>\r\n      <button class=\"btn-back\" onclick=\"goBack()\">\r\n        <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"19\" y1=\"12\" x2=\"5\" y2=\"12\"/><polyline points=\"12 19 5 12 12 5\"/></svg>\r\n        Back to Students\r\n      </button>\r\n    </div>\r\n\r\n    <!-- Tabs -->\r\n    <div class=\"tabs\" role=\"tablist\">\r\n      <button class=\"tab-btn active\" onclick=\"switchTab('generate')\">\r\n        <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 20h9\"/><path d=\"M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z\"/></svg>\r\n        Generate TC\r\n      </button>\r\n      <button class=\"tab-btn\" onclick=\"switchTab('issued')\">\r\n        <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><path d=\"m9 15 2 2 4-4\"/></svg>\r\n        Issued Certificates\r\n      </button>\r\n    </div>\r\n\r\n    <!-- Generate Tab -->\r\n    <div id=\"generateTab\" class=\"tab-content active\">\r\n      <!-- Search Panel -->\r\n      <div class=\"panel\">\r\n        <div class=\"panel-header\">\r\n          <div class=\"panel-title\">\r\n            <div class=\"icon-box\">\r\n              <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\r\n            </div>\r\n            <div>\r\n              <h3>Find Student</h3>\r\n              <p>Search for a student to generate TC</p>\r\n            </div>\r\n          </div>\r\n          <button class=\"btn btn-primary btn-sm\" onclick=\"loadAllStudents()\">\r\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"8\" y1=\"6\" x2=\"21\" y2=\"6\"/><line x1=\"8\" y1=\"12\" x2=\"21\" y2=\"12\"/><line x1=\"8\" y1=\"18\" x2=\"21\" y2=\"18\"/><line x1=\"3\" y1=\"6\" x2=\"3.01\" y2=\"6\"/><line x1=\"3\" y1=\"12\" x2=\"3.01\" y2=\"12\"/><line x1=\"3\" y1=\"18\" x2=\"3.01\" y2=\"18\"/></svg>\r\n            Show All Students\r\n          </button>\r\n        </div>\r\n\r\n        <div class=\"search-grid\">\r\n          <div class=\"field\">\r\n            <label>Student Name</label>\r\n            <div class=\"search-input-wrap\">\r\n              <svg class=\"search-icon\" width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\r\n              <input type=\"text\" id=\"searchName\" placeholder=\"Enter name...\" oninput=\"searchStudent()\" />\r\n            </div>\r\n          </div>\r\n          <div class=\"field\">\r\n            <label>Student ID</label>\r\n            <input type=\"text\" id=\"searchStudentId\" placeholder=\"e.g. STU001\" oninput=\"searchStudent()\" />\r\n          </div>\r\n          <div class=\"field\">\r\n            <label>Roll No</label>\r\n            <input type=\"text\" id=\"searchRoll\" placeholder=\"e.g. 12\" oninput=\"searchStudent()\" />\r\n          </div>\r\n          <div class=\"field\">\r\n            <label>Class</label>\r\n            <select id=\"searchClass\" onchange=\"searchStudent()\">\r\n              <option value=\"\">Select Class</option>\r\n            </select>\r\n          </div>\r\n        </div>\r\n\r\n        <div id=\"studentResult\">\r\n          <div class=\"empty-state\">\r\n            <div class=\"icon-circle\">\r\n              <svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\r\n            </div>\r\n            <h4>Search for a student</h4>\r\n            <p>Enter Student Name, ID, Roll No, or Class to find students</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- TC Form -->\r\n      <div class=\"panel\" id=\"tcFormSection\" style=\"display:none;\">\r\n        <div class=\"panel-header\">\r\n          <div class=\"panel-title\">\r\n            <div class=\"icon-box\">\r\n              <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg>\r\n            </div>\r\n            <div>\r\n              <h3>TC Details</h3>\r\n              <p>Fill certificate information</p>\r\n            </div>\r\n          </div>\r\n          <button class=\"btn btn-success\" onclick=\"showTCPREVIEW()\">\r\n            <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>\r\n            Preview TC\r\n          </button>\r\n        </div>\r\n\r\n        <div class=\"selected-strip\">\r\n          <div class=\"avatar\">\r\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2\"/><circle cx=\"12\" cy=\"7\" r=\"4\"/></svg>\r\n          </div>\r\n          <div>\r\n            <div class=\"label\">Selected Student</div>\r\n            <div class=\"name\" id=\"selectedStudentName\"></div>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"divider\">Certificate &amp; Reason</div>\r\n        <div class=\"form-row\">\r\n          <div class=\"field\">\r\n            <label>Reason for Leaving</label>\r\n            <select id=\"reason\">\r\n              <option value=\"\">Select reason</option>\r\n              <option>Personal Reasons</option>\r\n              <option>Parent Job Transfer</option>\r\n              <option>Change of Residence</option>\r\n              <option>Better Educational Opportunity</option>\r\n              <option>Migration to Another School</option>\r\n              <option>Completed Highest Class in School</option>\r\n              <option>Others</option>\r\n            </select>\r\n          </div>\r\n          <div class=\"field\"><label>TC / Certificate Number</label><input type=\"text\" id=\"tcNumber\" /></div>\r\n          <div class=\"field\"><label>Book No.</label><input type=\"text\" id=\"bookNo\" placeholder=\"e.g. 01\" /></div>\r\n          <div class=\"field\"><label>Date of Application</label><input type=\"date\" id=\"applicationDate\" /></div>\r\n          <div class=\"field\"><label>Date of Leaving (Struck off)</label><input type=\"date\" id=\"leavingDate\" /></div>\r\n          <div class=\"field\"><label>Date of Issue</label><input type=\"date\" id=\"issueDate\" /></div>\r\n          <div class=\"field\"><label>Place of Issue</label><input type=\"text\" id=\"placeOfIssue\" placeholder=\"City / Town\" /></div>\r\n        </div>\r\n\r\n        <div class=\"divider\">Parent / Guardian Details</div>\r\n        <div class=\"form-row\">\r\n          <div class=\"field\"><label>Father's Name</label><input type=\"text\" id=\"fatherName\" /></div>\r\n          <div class=\"field\"><label>Mother's Name</label><input type=\"text\" id=\"motherName\" /></div>\r\n          <div class=\"field\"><label>Guardian's Name</label><input type=\"text\" id=\"guardianName\" placeholder=\"If applicable\" /></div>\r\n          <div class=\"field\"><label>Nationality</label><input type=\"text\" id=\"nationality\" placeholder=\"Indian\" /></div>\r\n          <div class=\"field\"><label>Religion</label><input type=\"text\" id=\"religion\" placeholder=\"e.g. Hindu\" /></div>\r\n          <div class=\"field\"><label>Category (SC/ST/OBC/Gen)</label><input type=\"text\" id=\"category\" placeholder=\"General / SC / ST / OBC\" /></div>\r\n        </div>\r\n\r\n        <div class=\"divider\">Student &amp; Admission</div>\r\n        <div class=\"form-row\">\r\n          <div class=\"field\"><label>Admission / Register No.</label><input type=\"text\" id=\"admissionNo\" /></div>\r\n          <div class=\"field\"><label>Roll No</label><input type=\"text\" id=\"rollNo\" /></div>\r\n          <div class=\"field\"><label>Aadhaar / PAN No.</label><input type=\"text\" id=\"aadhaarPen\" placeholder=\"Optional\" /></div>\r\n          <div class=\"field\"><label>Date of Birth (figures)</label><input type=\"date\" id=\"dob\" /></div>\r\n          <div class=\"field\"><label>Date of Birth (in words)</label><input type=\"text\" id=\"dobWords\" placeholder=\"e.g. Fifth March Two Thousand Ten\" /></div>\r\n          <div class=\"field\"><label>Date of First Admission</label><input type=\"date\" id=\"admissionDate\" /></div>\r\n          <div class=\"field\"><label>Class in which Admitted</label><input type=\"text\" id=\"admittedClass\" placeholder=\"e.g. Nursery / I\" /></div>\r\n          <div class=\"field\"><label>Class Last Studied</label><input type=\"text\" id=\"lastClass\" /></div>\r\n          <div class=\"field\"><label>Section</label><input type=\"text\" id=\"section\" /></div>\r\n          <div class=\"field\"><label>Medium of Instruction</label><input type=\"text\" id=\"medium\" placeholder=\"English / Hindi\" /></div>\r\n        </div>\r\n\r\n        <div class=\"divider\">Academic Record</div>\r\n        <div class=\"form-row\">\r\n          <div class=\"field\"><label>Annual Exam Last Taken &amp; Result</label><input type=\"text\" id=\"lastExamResult\" /></div>\r\n          <div class=\"field\"><label>Whether Qualified for Promotion</label><input type=\"text\" id=\"qualifiedPromotion\" placeholder=\"Yes / No\" /></div>\r\n          <div class=\"field\"><label>Promoted to Class</label><input type=\"text\" id=\"promotedTo\" /></div>\r\n          <div class=\"field\"><label>Whether Failed / Repeated</label><input type=\"text\" id=\"failedRepeated\" placeholder=\"No\" /></div>\r\n          <div class=\"field\"><label>Subjects Studied</label><input type=\"text\" id=\"subjects\" placeholder=\"English, Hindi, Maths, Science, Social Science\" /></div>\r\n          <div class=\"field\"><label>Co-curricular / Games</label><input type=\"text\" id=\"coCurricular\" placeholder=\"e.g. Football, Music\" /></div>\r\n          <div class=\"field\"><label>NCC / Scout / Guide</label><input type=\"text\" id=\"nccScout\" placeholder=\"No\" /></div>\r\n          <div class=\"field\"><label>Total Working Days</label><input type=\"text\" id=\"workingDays\" placeholder=\"220\" /></div>\r\n          <div class=\"field\"><label>Total Days Present</label><input type=\"text\" id=\"daysPresent\" placeholder=\"210\" /></div>\r\n          <div class=\"field\"><label>General Conduct</label><input type=\"text\" id=\"conduct\" placeholder=\"Good\" /></div>\r\n        </div>\r\n\r\n        <div class=\"divider\">Fees &amp; Remarks</div>\r\n        <div class=\"form-row\">\r\n          <div class=\"field\"><label>School Dues Paid Upto</label><input type=\"text\" id=\"feesPaidUpto\" placeholder=\"Paid in Full\" /></div>\r\n          <div class=\"field\"><label>Fee Concession (if any)</label><input type=\"text\" id=\"feeConcession\" placeholder=\"Nil\" /></div>\r\n          <div class=\"field\"><label>Identification Mark (i)</label><input type=\"text\" id=\"identMark1\" /></div>\r\n          <div class=\"field\"><label>Identification Mark (ii)</label><input type=\"text\" id=\"identMark2\" /></div>\r\n          <div class=\"field\"><label>Remarks</label><input type=\"text\" id=\"remarks\" placeholder=\"Character &amp; conduct good\" /></div>\r\n        </div>\r\n\r\n        <div class=\"divider\">School &amp; Signatories</div>\r\n        <div class=\"form-row\">\r\n          <div class=\"field\"><label>School Name</label><input type=\"text\" id=\"schoolName\" /></div>\r\n          <div class=\"field\"><label>School Address</label><input type=\"text\" id=\"schoolAddress\" /></div>\r\n          <div class=\"field\"><label>Affiliation No.</label><input type=\"text\" id=\"affiliationNo\" placeholder=\"Optional\" /></div>\r\n          <div class=\"field\"><label>School Reg. / UDISE No.</label><input type=\"text\" id=\"udise\" placeholder=\"Optional\" /></div>\r\n          <div class=\"field\"><label>Class Teacher</label><input type=\"text\" id=\"classTeacher\" /></div>\r\n          <div class=\"field\"><label>Head Clerk / Accountant</label><input type=\"text\" id=\"clerk\" placeholder=\"Optional\" /></div>\r\n          <div class=\"field\"><label>Principal Name</label><input type=\"text\" id=\"principalName\" /></div>\r\n        </div>\r\n\r\n        <p style=\"margin-top:16px; font-size:12.5px; color: var(--text-muted); display:flex; align-items:center; gap:8px;\">\r\n          <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\r\n          Tip: In the preview you can click and edit <strong>every line</strong> of the certificate directly, including titles, labels and values, before saving or printing.\r\n        </p>\r\n      </div>\r\n\r\n      <!-- TC Preview -->\r\n      <div class=\"panel\" id=\"tcPreview\" style=\"display:none;\">\r\n        <div class=\"preview-header\">\r\n          <div class=\"panel-title\">\r\n            <div class=\"icon-box\">\r\n              <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>\r\n            </div>\r\n            <div>\r\n              <h3>TC Preview & Edit</h3>\r\n              <p>Review before printing</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"toolbar\">\r\n            <button class=\"btn btn-secondary btn-sm\" onclick=\"updatePreviewFromForm()\">\r\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"23 4 23 10 17 10\"/><polyline points=\"1 20 1 14 7 14\"/><path d=\"M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15\"/></svg>\r\n              Refresh Preview\r\n            </button>\r\n            <button class=\"btn btn-success btn-sm\" onclick=\"finalizeTC()\">\r\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 6 2 18 2 18 9\"/><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"/><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"/></svg>\r\n              Save & Print TC\r\n            </button>\r\n            <button class=\"btn btn-ghost btn-sm\" onclick=\"backToForm()\">\r\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"19\" y1=\"12\" x2=\"5\" y2=\"12\"/><polyline points=\"12 19 5 12 12 5\"/></svg>\r\n              Back to Form\r\n            </button>\r\n          </div>\r\n        </div>\r\n        <div class=\"edit-hint\">\r\n          <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 20h9\"/><path d=\"M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z\"/></svg>\r\n          Everything below is editable. Click any title, label or value to change it, then Save &amp; Print.\r\n        </div>\r\n        <div class=\"preview-content\" id=\"previewContent\"></div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Issued Tab -->\r\n    <div id=\"issuedTab\" class=\"tab-content\">\r\n      <div class=\"panel\">\r\n        <div class=\"panel-header\">\r\n          <div class=\"panel-title\">\r\n            <div class=\"icon-box\">\r\n              <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><path d=\"m9 15 2 2 4-4\"/></svg>\r\n            </div>\r\n            <div>\r\n              <h3>Issued Transfer Certificates</h3>\r\n              <p>Search, print or download previously issued TCs</p>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"search-grid\">\r\n          <div class=\"field\">\r\n            <label>Student</label>\r\n            <div class=\"search-input-wrap\">\r\n              <svg class=\"search-icon\" width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\r\n              <input type=\"text\" id=\"tcSearchStudent\" placeholder=\"Name or Student ID\" oninput=\"searchIssuedTCs()\" />\r\n            </div>\r\n          </div>\r\n          <div class=\"field\">\r\n            <label>TC Number</label>\r\n            <input type=\"text\" id=\"tcSearchNumber\" placeholder=\"e.g. TC-...\" oninput=\"searchIssuedTCs()\" />\r\n          </div>\r\n          <div class=\"field\">\r\n            <label>Class</label>\r\n            <select id=\"tcSearchClass\" onchange=\"searchIssuedTCs()\"><option value=\"\">All Classes</option></select>\r\n          </div>\r\n          <div class=\"field\">\r\n            <label>Issue Date</label>\r\n            <input type=\"date\" id=\"tcSearchDate\" onchange=\"searchIssuedTCs()\" />\r\n          </div>\r\n        </div>\r\n\r\n        <div id=\"issuedTCsList\"></div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Delete modal -->\r\n  <div class=\"delete-confirm\" id=\"deleteModal\">\r\n    <div class=\"delete-modal\">\r\n      <div class=\"icon-danger\">\r\n        <svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6l-2 14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L5 6\"/><path d=\"M10 11v6\"/><path d=\"M14 11v6\"/><path d=\"M9 6V4a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v2\"/></svg>\r\n      </div>\r\n      <h3>Delete TC</h3>\r\n      <p id=\"deleteMessage\">Are you sure you want to delete this TC?</p>\r\n      <div class=\"delete-actions\">\r\n        <button class=\"btn btn-secondary\" onclick=\"closeDeleteModal()\">Cancel</button>\r\n        <button class=\"btn\" style=\"background: var(--danger); color: #fff;\" id=\"confirmDelete\">Yes, Delete</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ================== SCRIPT (logic preserved) ================== -->\r\n  <script type=\"module\">\r\n    import { initializeApp } from \"./firebase-compat.js\";\r\n    import { getFirestore, collection, getDocs, getDoc, doc, addDoc, setDoc, updateDoc, deleteDoc, query, where, serverTimestamp } from \"./firebase-compat.js\";\r\n    import { getAuth, onAuthStateChanged } from \"./firebase-compat.js\";\r\n\r\n    const firebaseConfig = {\r\n apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n      authDomain: \"schoolix-48107.firebaseapp.com\",\r\n      projectId: \"schoolix-48107\",\r\n      storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n      messagingSenderId: \"133937954491\",\r\n      appId: \"1:133937954491:web:69d8064422617eb8c4339e\",\r\n      measurementId: \"G-EG23XE5Q0Z\"\r\n    };\r\n\r\n    const app = initializeApp(firebaseConfig);\r\n    const db = getFirestore(app);\r\n    const auth = getAuth(app);\r\n\r\n    let currentUser = null;\r\n    let allStudents = [];\r\n    let allTCs = [];\r\n    let selectedStudent = null;\r\n    let tcPreviewData = {};\r\n    let tcToDelete = null;\r\n\r\n    function esc(value) {\r\n      return String(value ?? \"\").replace(/[&<>\"']/g, (char) => ({\r\n        \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\"\r\n      }[char]));\r\n    }\r\n\r\n    function safeDateText(value) {\r\n      if (!value) return \"\";\r\n      const raw = value?.toDate ? value.toDate() : value;\r\n      const date = raw instanceof Date ? raw : new Date(raw);\r\n      return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleDateString(\"en-IN\");\r\n    }\r\n\r\n    function getPassoutYearFromTC(tcData = {}) {\r\n      const source = tcData.leavingDate || tcData.issueDate || tcData.generatedAt || new Date().toISOString();\r\n      const date = new Date(source);\r\n      if (!Number.isNaN(date.getTime())) return String(date.getFullYear());\r\n      const years = String(source).match(/\\b(20\\d{2}|19\\d{2})\\b/g);\r\n      return years?.length ? years[years.length - 1] : String(new Date().getFullYear());\r\n    }\r\n\r\n    async function loadStudentArchiveRecords(student = {}) {\r\n      const sid = student.studentId || student.id || \"\";\r\n      if (!sid) return { attendance: [], fees: [], reportCards: [] };\r\n      const [attendanceSnap, feesSnap, reportsSnap] = await Promise.all([\r\n        getDocs(query(collection(db, \"schools\", currentUser.uid, \"attendance\"), where(\"studentId\", \"==\", sid))),\r\n        getDocs(query(collection(db, \"schools\", currentUser.uid, \"fees\"), where(\"studentId\", \"==\", sid))),\r\n        getDocs(query(collection(db, \"schools\", currentUser.uid, \"reportCards\"), where(\"studentId\", \"==\", sid)))\r\n      ]);\r\n      return {\r\n        attendance: attendanceSnap.docs.map((d) => ({ id: d.id, ...d.data() })),\r\n        fees: feesSnap.docs.map((d) => ({ id: d.id, ...d.data() })),\r\n        reportCards: reportsSnap.docs.map((d) => ({ id: d.id, ...d.data() }))\r\n      };\r\n    }\r\n\r\n    async function archiveTCStudent(student, tcData, tcDocId) {\r\n      const archiveId = student.id || student.studentId;\r\n      const existingRecords = student.records || {};\r\n      const records = student._recordSource === \"archive\"\r\n        ? {\r\n            attendance: Array.isArray(existingRecords.attendance) ? existingRecords.attendance : [],\r\n            fees: Array.isArray(existingRecords.fees) ? existingRecords.fees : [],\r\n            reportCards: Array.isArray(existingRecords.reportCards) ? existingRecords.reportCards : []\r\n          }\r\n        : await loadStudentArchiveRecords(student);\r\n      await setDoc(doc(db, \"schools\", currentUser.uid, \"passedOutStudents\", archiveId), {\r\n        ...student,\r\n        _recordSource: null,\r\n        activeStudentDocId: student.id || \"\",\r\n        originalStudentDocId: student.id || \"\",\r\n        studentId: student.studentId || student.id || \"\",\r\n        passoutYear: student.passoutYear || getPassoutYearFromTC(tcData),\r\n        archiveReason: student.archiveReason || \"Transfer Certificate\",\r\n        archiveSource: \"transfer-certificate\",\r\n        status: student._recordSource === \"archive\" ? (student.status || \"Passed Out\") : \"TC Issued\",\r\n        finalClass: student.finalClass || student.class || \"\",\r\n        finalSection: student.finalSection || student.section || \"\",\r\n        tcIssued: true,\r\n        tcNumber: tcData.tcNumber || \"\",\r\n        tcCertificateDocId: tcDocId || \"\",\r\n        tcIssuedAt: tcData.generatedAt || new Date().toISOString(),\r\n        transferCertificate: { id: tcDocId || \"\", ...tcData },\r\n        records,\r\n        archivedAt: serverTimestamp(),\r\n        updatedAt: serverTimestamp()\r\n      }, { merge: true });\r\n      if (student._recordSource !== \"archive\") {\r\n        await deleteDoc(doc(db, \"schools\", currentUser.uid, \"students\", student.id));\r\n      }\r\n    }\r\n\r\n    function studentDisplayName(student) {\r\n      return student?.name || student?.studentName || \"N/A\";\r\n    }\r\n    function initials(name) {\r\n      return String(name || '?').split(/\\s+/).filter(Boolean).slice(0,2).map(w => w[0].toUpperCase()).join('') || '?';\r\n    }\r\n\r\n    function getStoredSchoolName() {\r\n      return window.SchoolBranding?.getSchoolName() || \"Schoolix School\";\r\n    }\r\n    function getDefaultSchoolAddress() {\r\n      return \"Affiliated to State Board\";\r\n    }\r\n\r\n    window.goBack = () => window.location.href = \"#/students.html\";\r\n\r\n    function showToast(message, type = 'success') {\r\n      const host = document.getElementById('toastHost');\r\n      const toast = document.createElement('div');\r\n      toast.className = `toast ${type}`;\r\n      const icon = type === 'error'\r\n        ? '<svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg>'\r\n        : '<svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg>';\r\n      toast.innerHTML = `${icon}<span>${esc(message)}</span>`;\r\n      host.appendChild(toast);\r\n      setTimeout(() => toast.remove(), 4000);\r\n    }\r\n\r\n    function showLoading(show, containerId) {\r\n      const container = document.getElementById(containerId);\r\n      if (!container) return;\r\n      if (show) container.innerHTML = '<div class=\"loading\"><div class=\"spinner\"></div><span>Loading...</span></div>';\r\n    }\r\n\r\n    window.switchTab = (tabName) => {\r\n      document.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));\r\n      document.querySelectorAll('.tab-content').forEach(content => content.classList.remove('active'));\r\n      document.querySelector(`[onclick=\"switchTab('${tabName}')\"]`).classList.add('active');\r\n      document.getElementById(tabName + 'Tab').classList.add('active');\r\n    };\r\n\r\n    window.showDeleteModal = (tcId, tcNumber) => {\r\n      tcToDelete = tcId;\r\n      document.getElementById('deleteMessage').textContent = `Are you sure you want to delete TC ${tcNumber}?`;\r\n      document.getElementById('deleteModal').classList.add('open');\r\n    };\r\n    window.closeDeleteModal = () => {\r\n      document.getElementById('deleteModal').classList.remove('open');\r\n      tcToDelete = null;\r\n    };\r\n    window.confirmDeleteTC = async () => {\r\n      if (!tcToDelete) return;\r\n      try {\r\n        const tcSnap = await getDoc(doc(db, \"schools\", currentUser.uid, \"transferCertificates\", tcToDelete));\r\n        const tcData = tcSnap.exists() ? tcSnap.data() : null;\r\n        await deleteDoc(doc(db, \"schools\", currentUser.uid, \"transferCertificates\", tcToDelete));\r\n        if (tcData?.studentDocId) {\r\n          await updateDoc(doc(db, \"schools\", currentUser.uid, \"students\", tcData.studentDocId), {\r\n            tcIssued: false, tcNumber: \"\", tcIssuedAt: null, tcCertificateDocId: null, updatedAt: serverTimestamp()\r\n          }).catch(() => {});\r\n        } else if (tcData?.studentId) {\r\n          const stSnap = await getDocs(query(collection(db, \"schools\", currentUser.uid, \"students\"), where(\"studentId\", \"==\", tcData.studentId)));\r\n          if (!stSnap.empty) {\r\n            await updateDoc(doc(db, \"schools\", currentUser.uid, \"students\", stSnap.docs[0].id), {\r\n              tcIssued: false, tcNumber: \"\", tcIssuedAt: null, tcCertificateDocId: null, updatedAt: serverTimestamp()\r\n            }).catch(() => {});\r\n          }\r\n        }\r\n        if (tcData?.archiveStudentDocId) {\r\n          await updateDoc(doc(db, \"schools\", currentUser.uid, \"passedOutStudents\", tcData.archiveStudentDocId), {\r\n            tcIssued: false,\r\n            tcNumber: \"\",\r\n            tcIssuedAt: null,\r\n            tcCertificateDocId: null,\r\n            transferCertificate: null,\r\n            status: \"Passed Out\",\r\n            updatedAt: serverTimestamp()\r\n          }).catch(() => {});\r\n        } else if (tcData?.studentId) {\r\n          const archivedSnap = await getDocs(query(collection(db, \"schools\", currentUser.uid, \"passedOutStudents\"), where(\"studentId\", \"==\", tcData.studentId)));\r\n          if (!archivedSnap.empty) {\r\n            await updateDoc(doc(db, \"schools\", currentUser.uid, \"passedOutStudents\", archivedSnap.docs[0].id), {\r\n              tcIssued: false,\r\n              tcNumber: \"\",\r\n              tcIssuedAt: null,\r\n              tcCertificateDocId: null,\r\n              transferCertificate: null,\r\n              status: \"Passed Out\",\r\n              updatedAt: serverTimestamp()\r\n            }).catch(() => {});\r\n          }\r\n        }\r\n        showToast('TC deleted. Student record unlocked.', 'success');\r\n        closeDeleteModal();\r\n        await loadIssuedTCs();\r\n        await loadStudents();\r\n      } catch (error) {\r\n        console.error(\"Error deleting TC:\", error);\r\n        showToast('Error deleting TC', 'error');\r\n      }\r\n    };\r\n\r\n    onAuthStateChanged(auth, async (user) => {\r\n      if (!user) { showToast('Please login first', 'error'); return window.location.href = \"#/index.html\"; }\r\n      currentUser = user;\r\n      try {\r\n        await Promise.all([loadStudents(), loadIssuedTCs()]);\r\n        switchTab('generate');\r\n      } catch (error) {\r\n        console.error('Error initializing:', error);\r\n        showToast('Error loading data: ' + error.message, 'error');\r\n      }\r\n    });\r\n\r\n    window.loadStudents = async () => {\r\n      if (!currentUser) { showToast('Please login first', 'error'); return; }\r\n      try {\r\n        showLoading(true, \"studentResult\");\r\n        const [studentSnap, archivedSnap] = await Promise.all([\r\n          getDocs(collection(db, \"schools\", currentUser.uid, \"students\")),\r\n          getDocs(collection(db, \"schools\", currentUser.uid, \"passedOutStudents\"))\r\n        ]);\r\n        allStudents = [];\r\n        studentSnap.forEach((d) => allStudents.push({ id: d.id, _recordSource: \"active\", ...d.data() }));\r\n        archivedSnap.forEach((d) => allStudents.push({ id: d.id, _recordSource: \"archive\", ...d.data() }));\r\n        populateClassFilter();\r\n        document.getElementById(\"studentResult\").innerHTML = emptySearchState();\r\n        showToast(`Loaded ${allStudents.length} students including passed out records.`, 'success');\r\n      } catch (error) {\r\n        console.error(\"Error loading students:\", error);\r\n        document.getElementById(\"studentResult\").innerHTML = `\r\n          <div class=\"error-state\">\r\n            <div class=\"icon-circle\"><svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg></div>\r\n            <h4>Error loading students</h4>\r\n            <p>${esc(error.message)}</p>\r\n            <button class=\"btn btn-primary btn-sm\" style=\"margin-top:12px;\" onclick=\"loadStudents()\">Retry</button>\r\n          </div>`;\r\n        showToast('Error loading students', 'error');\r\n      }\r\n    };\r\n\r\n    window.loadAllStudents = async () => { await loadStudents(); renderSearchResults(allStudents); };\r\n\r\n    window.searchStudent = () => {\r\n      const searchName = document.getElementById(\"searchName\")?.value?.trim().toLowerCase() || '';\r\n      const searchRoll = document.getElementById(\"searchRoll\")?.value?.trim() || '';\r\n      const searchClass = document.getElementById(\"searchClass\")?.value || '';\r\n      const searchStudentId = document.getElementById(\"searchStudentId\")?.value?.trim().toLowerCase() || '';\r\n      if (!searchName && !searchRoll && !searchClass && !searchStudentId) {\r\n        document.getElementById(\"studentResult\").innerHTML = emptySearchState();\r\n        return;\r\n      }\r\n      const found = allStudents.filter(s => {\r\n        const matchesName = !searchName || (studentDisplayName(s).toLowerCase().includes(searchName));\r\n        const matchesRoll = !searchRoll || (s.roll?.toString() === searchRoll);\r\n        const matchesClass = !searchClass || (s.class === searchClass) || (s.finalClass === searchClass);\r\n        const matchesId = !searchStudentId || (s.studentId?.toLowerCase().includes(searchStudentId));\r\n        return matchesName && matchesRoll && matchesClass && matchesId;\r\n      });\r\n      renderSearchResults(found);\r\n    };\r\n\r\n    function emptySearchState() {\r\n      return `<div class=\"empty-state\">\r\n        <div class=\"icon-circle\"><svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg></div>\r\n        <h4>Search for a student</h4>\r\n        <p>Enter Student Name, ID, Roll No, or Class to find students</p>\r\n      </div>`;\r\n    }\r\n\r\n    function renderSearchResults(students) {\r\n      const resultDiv = document.getElementById(\"studentResult\");\r\n      if (students.length === 0) {\r\n        resultDiv.innerHTML = `<div class=\"empty-state\">\r\n          <div class=\"icon-circle\"><svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"8\" y1=\"12\" x2=\"16\" y2=\"12\"/></svg></div>\r\n          <h4>No students found</h4><p>Try different search criteria or Show All Students</p></div>`;\r\n        return;\r\n      }\r\n      const html = '<div class=\"cards-list\">' + students.map(s => {\r\n        const issued = !!s.tcIssued;\r\n        const archived = s._recordSource === \"archive\";\r\n        const name = studentDisplayName(s);\r\n        return `\r\n        <div class=\"card-item ${issued ? 'tc-issued-card' : ''}\" data-student-id=\"${esc(s.id)}\" onclick=\"selectStudent('${esc(s.id)}')\">\r\n          <div class=\"card-head\">\r\n            <div class=\"card-title\">\r\n              <div class=\"avatar\">${esc(initials(name))}</div>\r\n              <span>${esc(name)}</span>\r\n            </div>\r\n            ${archived ? '<span class=\"pill pill-warning\">Passed Out</span>' : ''}\r\n            ${issued ? '<span class=\"pill pill-danger\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\"/><path d=\"M7 11V7a5 5 0 0 1 10 0v4\"/></svg>TC Issued</span>' : ''}\r\n          </div>\r\n          <div class=\"card-body-grid\">\r\n            <div><strong>Student ID:</strong>${esc(s.studentId || 'N/A')}</div>\r\n            <div><strong>Class:</strong>${esc(s.finalClass || s.class || '?')}${(s.finalSection || s.section) ? ' - ' + esc(s.finalSection || s.section) : ''}</div>\r\n            <div><strong>Roll No:</strong>${esc(s.roll || s.rollNo || '?')}</div>\r\n            ${archived ? `<div><strong>Passout Year:</strong>${esc(s.passoutYear || 'N/A')}</div>` : ''}\r\n            ${s.father ? `<div><strong>Father:</strong>${esc(s.father)}</div>` : ''}\r\n            ${s.mother ? `<div><strong>Mother:</strong>${esc(s.mother)}</div>` : ''}\r\n            ${s.phone ? `<div><strong>Phone:</strong>${esc(s.phone)}</div>` : ''}\r\n          </div>\r\n          ${issued ? '<div class=\"tc-note\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg>Transfer Certificate already issued. Cannot generate again.</div>' : ''}\r\n        </div>`;\r\n      }).join('') + '</div>';\r\n      resultDiv.innerHTML = html;\r\n    }\r\n\r\n    window.selectStudent = (id) => {\r\n      selectedStudent = allStudents.find(s => s.id === id);\r\n      if (!selectedStudent) { showToast('Student not found', 'error'); return; }\r\n      if (selectedStudent.tcIssued) { showToast('TC already issued for this student. Cannot generate again.', 'error'); return; }\r\n      document.querySelectorAll('.card-item').forEach(card => card.classList.remove('selected'));\r\n      const cardEl = document.querySelector(`.card-item[data-student-id=\"${id}\"]`);\r\n      if (cardEl) cardEl.classList.add('selected');\r\n      document.getElementById(\"selectedStudentName\").textContent = studentDisplayName(selectedStudent);\r\n      document.getElementById(\"tcFormSection\").style.display = \"block\";\r\n      populateTCForm();\r\n      document.getElementById(\"tcFormSection\").scrollIntoView({ behavior: 'smooth' });\r\n      showToast(`${studentDisplayName(selectedStudent)} selected. Fill TC details below.`, 'success');\r\n    };\r\n\r\n    function populateClassFilter() {\r\n      const classSet = new Set();\r\n      allStudents.forEach(s => {\r\n        if (s.class) classSet.add(s.class);\r\n        if (s.finalClass) classSet.add(s.finalClass);\r\n      });\r\n      const select = document.getElementById('searchClass');\r\n      select.innerHTML = '<option value=\"\">Select Class</option>';\r\n      Array.from(classSet).sort().forEach(c => { select.innerHTML += `<option value=\"${esc(c)}\">${esc(c)}</option>`; });\r\n    }\r\n\r\n    function populateTCForm() {\r\n      if (!selectedStudent) return;\r\n      const today = new Date().toISOString().split('T')[0];\r\n      const iso = (v) => v ? new Date(v).toISOString().split('T')[0] : '';\r\n      const set = (id, val) => { const el = document.getElementById(id); if (el) el.value = val ?? ''; };\r\n      const s = selectedStudent;\r\n      set(\"tcNumber\", `TC-${s.studentId || s.id || 'N/A'}-${Date.now().toString().slice(-6)}`);\r\n      set(\"bookNo\", \"\");\r\n      set(\"applicationDate\", today);\r\n      set(\"leavingDate\", today);\r\n      set(\"issueDate\", today);\r\n      set(\"placeOfIssue\", \"\");\r\n      // Parent / guardian\r\n      set(\"fatherName\", s.father || s.fatherName || '');\r\n      set(\"motherName\", s.mother || s.motherName || '');\r\n      set(\"guardianName\", s.guardian || s.guardianName || '');\r\n      set(\"nationality\", s.nationality || 'Indian');\r\n      set(\"religion\", s.religion || '');\r\n      set(\"category\", s.category || 'General');\r\n      // Student / admission\r\n      set(\"admissionNo\", s.admissionNo || s.studentId || '');\r\n      set(\"rollNo\", s.roll || s.rollNo || '');\r\n      set(\"aadhaarPen\", s.aadhaar || s.pen || '');\r\n      set(\"dob\", iso(s.dob));\r\n      set(\"dobWords\", \"\");\r\n      set(\"admissionDate\", iso(s.admissionDate));\r\n      set(\"admittedClass\", s.admittedClass || '');\r\n      const lastClass = s.finalClass || s.class || \"\";\r\n      const lastSection = s.finalSection || s.section || \"\";\r\n      set(\"lastClass\", `${lastClass}${lastSection ? ` (${lastSection})` : ''}`.trim());\r\n      set(\"section\", s.section || '');\r\n      set(\"medium\", s.medium || 'English');\r\n      // Academic\r\n      set(\"lastExamResult\", `Passed Class ${s.class || 'N/A'}`);\r\n      set(\"qualifiedPromotion\", \"Yes\");\r\n      set(\"promotedTo\", \"\");\r\n      set(\"failedRepeated\", \"No\");\r\n      set(\"subjects\", \"English, Hindi, Mathematics, Science, Social Science\");\r\n      set(\"coCurricular\", \"\");\r\n      set(\"nccScout\", \"No\");\r\n      set(\"workingDays\", \"220\");\r\n      set(\"daysPresent\", \"210\");\r\n      set(\"conduct\", \"Good\");\r\n      // Fees / remarks\r\n      set(\"feesPaidUpto\", \"Paid in Full\");\r\n      set(\"feeConcession\", \"Nil\");\r\n      set(\"identMark1\", \"\");\r\n      set(\"identMark2\", \"\");\r\n      set(\"remarks\", \"Character and Conduct Good\");\r\n      // School / signatories\r\n      set(\"schoolName\", getStoredSchoolName());\r\n      set(\"schoolAddress\", getDefaultSchoolAddress());\r\n      set(\"affiliationNo\", \"\");\r\n      set(\"udise\", \"\");\r\n      set(\"classTeacher\", s.classTeacher || 'Class Teacher');\r\n      set(\"clerk\", \"\");\r\n      set(\"principalName\", 'Principal');\r\n    }\r\n\r\n    window.showTCPREVIEW = () => {\r\n      if (!selectedStudent) { showToast('Please select a student first', 'error'); return; }\r\n      const data = getFormData();\r\n      if (!data.reason || !data.leavingDate || !data.tcNumber) {\r\n        showToast(\"Reason, leaving date and TC number are required.\", \"error\"); return;\r\n      }\r\n      tcPreviewData = { ...data, studentId: selectedStudent.studentId, studentName: studentDisplayName(selectedStudent) };\r\n      renderPreview();\r\n      document.getElementById(\"tcPreview\").style.display = \"block\";\r\n      document.getElementById(\"tcFormSection\").style.display = \"none\";\r\n      document.getElementById(\"tcPreview\").scrollIntoView({ behavior: 'smooth' });\r\n    };\r\n\r\n    function getFormData() {\r\n      const val = (id) => document.getElementById(id)?.value ?? '';\r\n      return {\r\n        reason: val(\"reason\"),\r\n        tcNumber: val(\"tcNumber\"),\r\n        bookNo: val(\"bookNo\"),\r\n        applicationDate: val(\"applicationDate\"),\r\n        leavingDate: val(\"leavingDate\"),\r\n        issueDate: val(\"issueDate\"),\r\n        placeOfIssue: val(\"placeOfIssue\"),\r\n        fatherName: val(\"fatherName\"),\r\n        motherName: val(\"motherName\"),\r\n        guardianName: val(\"guardianName\"),\r\n        nationality: val(\"nationality\"),\r\n        religion: val(\"religion\"),\r\n        category: val(\"category\"),\r\n        admissionNo: val(\"admissionNo\"),\r\n        rollNo: val(\"rollNo\"),\r\n        aadhaarPen: val(\"aadhaarPen\"),\r\n        dob: val(\"dob\"),\r\n        dobWords: val(\"dobWords\"),\r\n        admissionDate: val(\"admissionDate\"),\r\n        admittedClass: val(\"admittedClass\"),\r\n        lastClass: val(\"lastClass\"),\r\n        section: val(\"section\"),\r\n        medium: val(\"medium\"),\r\n        lastExamResult: val(\"lastExamResult\"),\r\n        qualifiedPromotion: val(\"qualifiedPromotion\"),\r\n        promotedTo: val(\"promotedTo\"),\r\n        failedRepeated: val(\"failedRepeated\"),\r\n        subjects: val(\"subjects\"),\r\n        coCurricular: val(\"coCurricular\"),\r\n        nccScout: val(\"nccScout\"),\r\n        workingDays: val(\"workingDays\"),\r\n        daysPresent: val(\"daysPresent\"),\r\n        conduct: val(\"conduct\"),\r\n        feesPaidUpto: val(\"feesPaidUpto\"),\r\n        feeConcession: val(\"feeConcession\"),\r\n        identMark1: val(\"identMark1\"),\r\n        identMark2: val(\"identMark2\"),\r\n        remarks: val(\"remarks\"),\r\n        schoolName: val(\"schoolName\"),\r\n        schoolAddress: val(\"schoolAddress\"),\r\n        affiliationNo: val(\"affiliationNo\"),\r\n        udise: val(\"udise\"),\r\n        classTeacher: val(\"classTeacher\"),\r\n        clerk: val(\"clerk\"),\r\n        principal: val(\"principalName\")\r\n      };\r\n    }\r\n\r\n    // Renders an inline-editable value span so every value can be edited in the preview\r\n    function ef(key, value, placeholder = '-') {\r\n      return `<span class=\"editable-field\" contenteditable=\"true\" data-key=\"${esc(key)}\" data-placeholder=\"${esc(placeholder)}\">${esc(value ?? '')}</span>`;\r\n    }\r\n\r\n    // Reads every edited value back out of the preview into a plain object\r\n    function collectEditedData() {\r\n      const previewContent = document.getElementById(\"previewContent\");\r\n      const out = {};\r\n      previewContent.querySelectorAll('[data-key]').forEach(node => {\r\n        out[node.dataset.key] = node.textContent.trim();\r\n      });\r\n      out.previewHtml = previewContent.innerHTML;\r\n      return out;\r\n    }\r\n\r\n    function renderPreview() {\r\n      const previewContent = document.getElementById(\"previewContent\");\r\n      const d = tcPreviewData;\r\n      const issueTxt = d.issueDate ? new Date(d.issueDate).toLocaleDateString('en-IN') : new Date().toLocaleDateString('en-IN');\r\n      previewContent.setAttribute('contenteditable', 'true');\r\n      previewContent.spellcheck = false;\r\n      previewContent.innerHTML = `\r\n        <h2>TRANSFER CERTIFICATE</h2>\r\n        <div class=\"school-name\">${ef('schoolName', d.schoolName || getStoredSchoolName(), 'School name')}</div>\r\n        <div class=\"school-addr\">${ef('schoolAddress', d.schoolAddress || getDefaultSchoolAddress(), 'School address')}\r\n          <div style=\"font-size:12px; color:#64748b; margin-top:4px;\">\r\n            Affiliation No: ${ef('affiliationNo', d.affiliationNo, '-')} &nbsp;|&nbsp; Reg./UDISE No: ${ef('udise', d.udise, '-')}\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"meta-row\">\r\n          <div><strong>Certificate No:</strong> ${ef('tcNumber', d.tcNumber, '-')}<br/>\r\n               <strong>Book No:</strong> ${ef('bookNo', d.bookNo, '-')}<br/>\r\n               <strong>Admission / Register No:</strong> ${ef('admissionNo', d.admissionNo, '-')}</div>\r\n          <div style=\"text-align:right;\"><strong>Date of Issue:</strong> ${ef('issueDateText', issueTxt, '-')}<br/>\r\n               <strong>Place:</strong> ${ef('placeOfIssue', d.placeOfIssue, '-')}</div>\r\n        </div>\r\n\r\n        <div class=\"tc-field\"><strong>1. Name of Pupil:</strong> ${ef('studentName', d.studentName)}</div>\r\n        <div class=\"tc-field\"><strong>2. Mother's Name:</strong> ${ef('motherName', d.motherName)}</div>\r\n        <div class=\"tc-field\"><strong>3. Father's Name:</strong> ${ef('fatherName', d.fatherName)}</div>\r\n        <div class=\"tc-field\"><strong>4. Guardian's Name:</strong> ${ef('guardianName', d.guardianName)}</div>\r\n        <div class=\"tc-field\"><strong>5. Nationality:</strong> ${ef('nationality', d.nationality || 'Indian')}</div>\r\n        <div class=\"tc-field\"><strong>6. Religion:</strong> ${ef('religion', d.religion)}</div>\r\n        <div class=\"tc-field\"><strong>7. Category (SC/ST/OBC/Gen):</strong> ${ef('category', d.category || 'General')}</div>\r\n        <div class=\"tc-field\"><strong>8. Aadhaar / PEN No:</strong> ${ef('aadhaarPen', d.aadhaarPen)}</div>\r\n        <div class=\"tc-field\"><strong>9. Date of Birth (in figures):</strong> ${ef('dob', safeDateText(d.dob))}</div>\r\n        <div class=\"tc-field\"><strong>10. Date of Birth (in words):</strong> ${ef('dobWords', d.dobWords)}</div>\r\n        <div class=\"tc-field\"><strong>11. Date of First Admission:</strong> ${ef('admissionDate', safeDateText(d.admissionDate))}</div>\r\n        <div class=\"tc-field\"><strong>12. Class in which Admitted:</strong> ${ef('admittedClass', d.admittedClass)}</div>\r\n        <div class=\"tc-field\"><strong>13. Class in which Last Studied:</strong> ${ef('lastClass', d.lastClass)}</div>\r\n        <div class=\"tc-field\"><strong>14. Section:</strong> ${ef('section', d.section)}</div>\r\n        <div class=\"tc-field\"><strong>15. Medium of Instruction:</strong> ${ef('medium', d.medium || 'English')}</div>\r\n        <div class=\"tc-field\"><strong>16. Roll No:</strong> ${ef('rollNo', d.rollNo)}</div>\r\n        <div class=\"tc-field\"><strong>17. Annual Exam Last Taken &amp; Result:</strong> ${ef('lastExamResult', d.lastExamResult)}</div>\r\n        <div class=\"tc-field\"><strong>18. Whether Qualified for Promotion:</strong> ${ef('qualifiedPromotion', d.qualifiedPromotion || 'Yes')}</div>\r\n        <div class=\"tc-field\"><strong>19. Promoted to Class:</strong> ${ef('promotedTo', d.promotedTo)}</div>\r\n        <div class=\"tc-field\"><strong>20. Whether Failed / Repeated:</strong> ${ef('failedRepeated', d.failedRepeated || 'No')}</div>\r\n        <div class=\"tc-field\"><strong>21. Subjects Studied:</strong> ${ef('subjects', d.subjects || 'English, Hindi, Mathematics, Science, Social Science')}</div>\r\n        <div class=\"tc-field\"><strong>22. Co-curricular Activities / Games:</strong> ${ef('coCurricular', d.coCurricular)}</div>\r\n        <div class=\"tc-field\"><strong>23. Whether NCC Cadet / Scout / Guide:</strong> ${ef('nccScout', d.nccScout || 'No')}</div>\r\n        <div class=\"tc-field\"><strong>24. Total No. of Working Days:</strong> ${ef('workingDays', d.workingDays || '220')}</div>\r\n        <div class=\"tc-field\"><strong>25. Total No. of Days Present:</strong> ${ef('daysPresent', d.daysPresent || '210')}</div>\r\n        <div class=\"tc-field\"><strong>26. School Dues Paid Upto:</strong> ${ef('feesPaidUpto', d.feesPaidUpto || 'Paid in Full')}</div>\r\n        <div class=\"tc-field\"><strong>27. Fee Concession (if any):</strong> ${ef('feeConcession', d.feeConcession || 'Nil')}</div>\r\n        <div class=\"tc-field\"><strong>28. General Conduct:</strong> ${ef('conduct', d.conduct || 'Good')}</div>\r\n        <div class=\"tc-field\"><strong>29. Date of Application for Certificate:</strong> ${ef('applicationDate', safeDateText(d.applicationDate))}</div>\r\n        <div class=\"tc-field\"><strong>30. Date of Leaving School / Struck Off:</strong> ${ef('leavingDate', safeDateText(d.leavingDate))}</div>\r\n        <div class=\"tc-field\"><strong>31. Reason for Leaving School:</strong> ${ef('reason', d.reason)}</div>\r\n        <div class=\"tc-field\"><strong>32. Identification Mark (i):</strong> ${ef('identMark1', d.identMark1)}</div>\r\n        <div class=\"tc-field\"><strong>33. Identification Mark (ii):</strong> ${ef('identMark2', d.identMark2)}</div>\r\n        <div class=\"tc-field\"><strong>34. Any Other Remarks:</strong> ${ef('remarks', d.remarks || 'Character and Conduct Good')}</div>\r\n\r\n        <div class=\"sig-row\">\r\n          <div class=\"sig-box\"><div class=\"sig-line\"></div><strong>Prepared / Clerk</strong><div>${ef('clerk', d.clerk)}</div></div>\r\n          <div class=\"sig-box\"><div class=\"sig-line\"></div><strong>Class Teacher</strong><div>${ef('classTeacher', d.classTeacher)}</div></div>\r\n          <div class=\"sig-box\"><div class=\"sig-line\"></div><strong>Principal / Head</strong><div>${ef('principal', d.principal)}</div></div>\r\n        </div>\r\n      `;\r\n    }\r\n\r\n    window.updatePreviewFromForm = () => {\r\n      if (!selectedStudent) return;\r\n      tcPreviewData = { ...getFormData(), studentId: selectedStudent.studentId, studentName: studentDisplayName(selectedStudent) };\r\n      renderPreview();\r\n      showToast('Preview updated from form.', 'success');\r\n    };\r\n\r\n    window.backToForm = () => {\r\n      document.getElementById(\"tcPreview\").style.display = \"none\";\r\n      document.getElementById(\"tcFormSection\").style.display = \"block\";\r\n    };\r\n\r\n    window.finalizeTC = async () => {\r\n      if (!selectedStudent) { showToast('Please select a student first', 'error'); return; }\r\n      if (selectedStudent.tcIssued) { showToast('This student already has a TC issued.', 'error'); return; }\r\n      try {\r\n        const edited = collectEditedData();\r\n        const finalData = {\r\n          ...tcPreviewData,\r\n          ...edited,\r\n          studentId: selectedStudent.studentId,\r\n          studentName: studentDisplayName(selectedStudent),\r\n          class: selectedStudent.finalClass || selectedStudent.class || 'N/A',\r\n          section: selectedStudent.finalSection || selectedStudent.section || '',\r\n          roll: selectedStudent.roll || 'N/A',\r\n          generatedBy: currentUser.uid,\r\n          generatedAt: new Date().toISOString(),\r\n          studentDocId: selectedStudent._recordSource === \"archive\" ? \"\" : selectedStudent.id,\r\n          archiveStudentDocId: selectedStudent._recordSource === \"archive\" ? selectedStudent.id : \"\"\r\n        };\r\n        if (!finalData.leavingDate) { showToast('Please set leaving date', 'error'); return; }\r\n        if (!finalData.tcNumber) { showToast('Please enter TC number', 'error'); return; }\r\n        const duplicateSnap = await getDocs(query(\r\n          collection(db, \"schools\", currentUser.uid, \"transferCertificates\"),\r\n          where(\"studentId\", \"==\", selectedStudent.studentId)\r\n        ));\r\n        if (!duplicateSnap.empty) {\r\n          showToast(\"TC already exists for this student. Refreshing records.\", \"error\");\r\n          await loadIssuedTCs(); return;\r\n        }\r\n        const docRef = await addDoc(collection(db, \"schools\", currentUser.uid, \"transferCertificates\"), finalData);\r\n        await archiveTCStudent(selectedStudent, finalData, docRef.id);\r\n        if (selectedStudent._recordSource === \"archive\") {\r\n          allStudents = allStudents.map((s) => s.id === selectedStudent.id ? {\r\n            ...s,\r\n            tcIssued: true,\r\n            tcNumber: finalData.tcNumber || \"\",\r\n            tcCertificateDocId: docRef.id,\r\n            transferCertificate: { id: docRef.id, ...finalData },\r\n            status: s.status || \"Passed Out\"\r\n          } : s);\r\n        } else {\r\n          allStudents = allStudents.filter((s) => s.id !== selectedStudent.id);\r\n        }\r\n        selectedStudent = null;\r\n        showToast(`TC ${finalData.tcNumber} saved and uploaded to student dashboard.`, 'success');\r\n        await loadIssuedTCs();\r\n        generateAndPrintTC(finalData);\r\n        resetForm();\r\n        switchTab('issued');\r\n      } catch (error) {\r\n        console.error(\"Error saving TC:\", error);\r\n        showToast('Error saving TC: ' + error.message, 'error');\r\n      }\r\n    };\r\n\r\n    function resetForm() {\r\n      document.getElementById(\"tcPreview\").style.display = \"none\";\r\n      document.getElementById(\"tcFormSection\").style.display = \"none\";\r\n      selectedStudent = null;\r\n      tcPreviewData = {};\r\n      document.getElementById(\"selectedStudentName\").textContent = '';\r\n      document.querySelectorAll('#tcFormSection input, #tcFormSection select, #tcFormSection textarea').forEach(el => { el.value = ''; });\r\n      ['searchName', 'searchRoll', 'searchClass', 'searchStudentId'].forEach(id => {\r\n        const el = document.getElementById(id); if (el) el.value = '';\r\n      });\r\n      document.getElementById(\"studentResult\").innerHTML = emptySearchState();\r\n    }\r\n\r\n    async function loadIssuedTCs() {\r\n      try {\r\n        showLoading(true, \"issuedTCsList\");\r\n        const tcSnap = await getDocs(collection(db, \"schools\", currentUser.uid, \"transferCertificates\"));\r\n        allTCs = tcSnap.docs.map(d => ({ id: d.id, ...d.data() })).sort((a,b) => new Date(b.generatedAt || 0) - new Date(a.generatedAt || 0));\r\n        populateTCClassFilter();\r\n        renderIssuedTCs(allTCs);\r\n      } catch (error) {\r\n        console.error(\"Error loading TCs:\", error);\r\n        showToast('Error loading TCs', 'error');\r\n      }\r\n    }\r\n\r\n    window.searchIssuedTCs = () => {\r\n      const searchStudent = document.getElementById(\"tcSearchStudent\")?.value?.trim().toLowerCase() || '';\r\n      const searchNumber = document.getElementById(\"tcSearchNumber\")?.value?.trim().toLowerCase() || '';\r\n      const searchClass = document.getElementById(\"tcSearchClass\")?.value || '';\r\n      const searchDate = document.getElementById(\"tcSearchDate\")?.value || '';\r\n      let filtered = allTCs.filter(tc => {\r\n        if (searchStudent && !tc.studentName?.toLowerCase().includes(searchStudent) && !tc.studentId?.toLowerCase().includes(searchStudent)) return false;\r\n        if (searchNumber && !tc.tcNumber?.toLowerCase().includes(searchNumber)) return false;\r\n        if (searchClass && tc.class !== searchClass) return false;\r\n        if (searchDate) {\r\n          const generated = new Date(tc.generatedAt || 0);\r\n          if (Number.isNaN(generated.getTime()) || generated.toISOString().split('T')[0] !== searchDate) return false;\r\n        }\r\n        return true;\r\n      });\r\n      renderIssuedTCs(filtered);\r\n    };\r\n\r\n    function renderIssuedTCs(tcs) {\r\n      const resultDiv = document.getElementById(\"issuedTCsList\");\r\n      if (tcs.length === 0) {\r\n        resultDiv.innerHTML = `<div class=\"empty-state\">\r\n          <div class=\"icon-circle\"><svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg></div>\r\n          <h4>No TCs found</h4><p>No transfer certificates match your search criteria</p></div>`;\r\n        return;\r\n      }\r\n      const html = '<div class=\"cards-list\">' + tcs.map(tc => `\r\n        <div class=\"card-item\" style=\"cursor:default; border-left: 4px solid var(--success);\">\r\n          <div class=\"card-head\">\r\n            <div class=\"card-title\">\r\n              <div class=\"avatar\" style=\"background: var(--success-50); color: var(--success);\">\r\n                <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg>\r\n              </div>\r\n              <span>TC: ${esc(tc.tcNumber || 'N/A')}</span>\r\n            </div>\r\n            <span class=\"pill pill-success\">Issued</span>\r\n          </div>\r\n          <div class=\"card-body-grid\">\r\n            <div><strong>Student:</strong>${esc(tc.studentName || 'N/A')}</div>\r\n            <div><strong>ID:</strong>${esc(tc.studentId || 'N/A')}</div>\r\n            <div><strong>Class:</strong>${esc(tc.class || 'N/A')}${tc.section ? ` (${esc(tc.section)})` : ''}</div>\r\n            <div><strong>Issued:</strong>${esc(safeDateText(tc.generatedAt))}</div>\r\n            <div style=\"grid-column: 1 / -1;\"><strong>Reason:</strong>${esc(tc.reason || '')}</div>\r\n          </div>\r\n          <div class=\"toolbar\" style=\"margin-top: 14px;\">\r\n            <button class=\"btn btn-primary btn-sm\" onclick=\"printTC('${esc(tc.id)}')\">\r\n              <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 6 2 18 2 18 9\"/><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"/><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"/></svg>\r\n              Print TC\r\n            </button>\r\n            <button class=\"btn btn-secondary btn-sm\" onclick=\"downloadTCPDF('${esc(tc.id)}')\">\r\n              <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\r\n              Download PDF\r\n            </button>\r\n          </div>\r\n        </div>\r\n      `).join('') + '</div>';\r\n      resultDiv.innerHTML = html;\r\n    }\r\n\r\n    function populateTCClassFilter() {\r\n      const classSet = new Set();\r\n      allTCs.forEach(tc => { if (tc.class) classSet.add(tc.class); });\r\n      const select = document.getElementById('tcSearchClass');\r\n      select.innerHTML = '<option value=\"\">All Classes</option>';\r\n      Array.from(classSet).sort().forEach(c => { select.innerHTML += `<option value=\"${esc(c)}\">${esc(c)}</option>`; });\r\n    }\r\n\r\n    function generateAndPrintTC(tcData) {\r\n      const htmlContent = generateTCHTML(tcData);\r\n      const printWindow = window.open('', '_blank');\r\n      if (!printWindow) { showToast(\"Popup blocked. Allow popups to print TC.\", \"error\"); return; }\r\n      printWindow.document.write(htmlContent);\r\n      printWindow.document.close();\r\n      setTimeout(() => printWindow.print(), 500);\r\n    }\r\n\r\n    function tcPrintStyles() {\r\n      return `\r\n        @page { size: A4; margin: 16mm; }\r\n        body { font-family: 'Times New Roman', Georgia, serif; color: #111; padding: 0; margin: 0; }\r\n        .tc-container { max-width: 800px; margin: 0 auto; padding: 30px; border: 2px solid #333; }\r\n        h2 { text-align: center; font-size: 26px; letter-spacing: 4px; margin: 0 0 8px; }\r\n        .school-name { text-align: center; font-size: 20px; font-weight: bold; }\r\n        .school-addr { text-align: center; font-size: 14px; color: #444; padding-bottom: 14px; margin-bottom: 20px; border-bottom: 2px double #333; }\r\n        .meta-row { display: flex; justify-content: space-between; margin-bottom: 22px; font-size: 14px; gap: 20px; }\r\n        .tc-field { font-size: 14.5px; margin: 8px 0; }\r\n        .tc-field strong { display: inline-block; min-width: 300px; }\r\n        .sig-row { display: flex; justify-content: space-between; margin-top: 64px; gap: 24px; }\r\n        .sig-box { text-align: center; flex: 1; }\r\n        .sig-line { border-top: 1.5px solid #333; margin-bottom: 6px; height: 40px; }\r\n        /* Neutralise the on-screen editable styling for a clean printout */\r\n        .editable-field { border: none !important; background: transparent !important; padding: 0 !important; min-width: 0 !important; box-shadow: none !important; font: inherit !important; }\r\n        [contenteditable] { outline: none; }\r\n        @media print { body { margin: 0; padding: 0; } .tc-container { border: none; } }\r\n      `;\r\n    }\r\n\r\n    function generateTCHTML(tcData) {\r\n      // Prefer the exact certificate the user edited inline in the preview\r\n      const body = tcData.previewHtml\r\n        ? tcData.previewHtml\r\n        : fallbackTCBody(tcData);\r\n      return `<!DOCTYPE html><html><head>\r\n<meta charset=\"UTF-8\">\r\n        <title>Transfer Certificate - ${esc(tcData.studentName || '')}</title>\r\n        <style>${tcPrintStyles()}</style>\r\n</head><body><div class=\"tc-container\">${body}</div>","styles":[{"tag":"style","attributes":{"id":"sxCriticalLoaderStyle"},"text":"\r\nhtml.sx-page-loading,\r\nhtml.sx-page-loading body {\r\n  min-height: 100%;\r\n  background: #f8fafc !important;\r\n}\r\nhtml.sx-page-loading body::before,\r\nhtml.sx-page-loading body::after {\r\n  visibility: hidden !important;\r\n}\r\nhtml.sx-page-loading body > :not(#sxPageLoader):not(script):not(style) {\r\n  visibility: hidden !important;\r\n}\r\n.sx-page-loader {\r\n  position: fixed;\r\n  inset: 0;\r\n  z-index: 2147482500;\r\n  display: flex;\r\n  align-items: stretch;\r\n  justify-content: stretch;\r\n  background: #f8fafc;\r\n  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.25s ease;\r\n  overflow: hidden;\r\n}\r\n.sx-page-loader.is-hidden {\r\n  opacity: 0;\r\n  visibility: hidden;\r\n  pointer-events: none;\r\n}\r\n.sx-page-loader .dots-container {\r\n  position: fixed;\r\n  inset: 0;\r\n  display: block;\r\n  width: 100vw;\r\n  height: 100vh;\r\n  padding: 0;\r\n  margin: 0;\r\n  overflow: hidden;\r\n  background: #f8fafc;\r\n}\r\n.sx-page-loader .dots-container::before,\r\n.sx-page-loader .dots-container::after,\r\n.sx-page-loader .dot {\r\n  display: none !important;\r\n}\r\n"},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"admin-shell.css?v=navbar-20260721"},"text":""}],"scripts":[{"attributes":{"id":"sxCriticalLoaderScript"},"text":"\r\n(function () {\r\n  var root = document.documentElement;\r\n  root.classList.add(\"sx-page-loading\");\r\n  window.SchoolixPageLoaderEarly = window.SchoolixPageLoaderEarly || { startedAt: Date.now() };\r\n\r\n  function markEarlyReady(reason) {\r\n    window.SchoolixPageLoaderEarly.ready = true;\r\n    window.SchoolixPageLoaderEarly.reason = reason || \"dom-ready\";\r\n    try {\r\n      window.dispatchEvent(new CustomEvent(\"schoolix:critical-load-ready\", { detail: window.SchoolixPageLoaderEarly }));\r\n    } catch (_) {}\r\n  }\r\n\r\n  function afterFirstPaint(reason) {\r\n    requestAnimationFrame(function () {\r\n      requestAnimationFrame(function () { markEarlyReady(reason); });\r\n    });\r\n  }\r\n\r\n  function emergencyHide() {\r\n    if (window.SchoolixPageLoader || !root.classList.contains(\"sx-page-loading\")) return;\r\n    root.classList.remove(\"sx-page-loading\");\r\n    root.classList.add(\"sx-page-loaded\");\r\n    var loader = document.getElementById(\"sxPageLoader\");\r\n    if (!loader) return;\r\n    loader.classList.add(\"is-hidden\");\r\n    setTimeout(function () { loader.remove(); }, 260);\r\n  }\r\n\r\n  if (document.readyState === \"loading\") {\r\n    document.addEventListener(\"DOMContentLoaded\", function () { afterFirstPaint(\"dom-ready\"); }, { once: true });\r\n  } else {\r\n    afterFirstPaint(document.readyState === \"complete\" ? \"document-complete\" : \"dom-ready\");\r\n  }\r\n  window.addEventListener(\"load\", function () { markEarlyReady(\"window-load\"); }, { once: true });\r\n  setTimeout(emergencyHide, 3200);\r\n}());\r\n"},{"attributes":{"type":"module"},"text":"\r\n    import { initializeApp } from \"./firebase-compat.js\";\r\n    import { getFirestore, collection, getDocs, getDoc, doc, addDoc, setDoc, updateDoc, deleteDoc, query, where, serverTimestamp } from \"./firebase-compat.js\";\r\n    import { getAuth, onAuthStateChanged } from \"./firebase-compat.js\";\r\n\r\n    const firebaseConfig = {\r\n apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n      authDomain: \"schoolix-48107.firebaseapp.com\",\r\n      projectId: \"schoolix-48107\",\r\n      storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n      messagingSenderId: \"133937954491\",\r\n      appId: \"1:133937954491:web:69d8064422617eb8c4339e\",\r\n      measurementId: \"G-EG23XE5Q0Z\"\r\n    };\r\n\r\n    const app = initializeApp(firebaseConfig);\r\n    const db = getFirestore(app);\r\n    const auth = getAuth(app);\r\n\r\n    let currentUser = null;\r\n    let allStudents = [];\r\n    let allTCs = [];\r\n    let selectedStudent = null;\r\n    let tcPreviewData = {};\r\n    let tcToDelete = null;\r\n\r\n    function esc(value) {\r\n      return String(value ?? \"\").replace(/[&<>\"']/g, (char) => ({\r\n        \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\"\r\n      }[char]));\r\n    }\r\n\r\n    function safeDateText(value) {\r\n      if (!value) return \"\";\r\n      const raw = value?.toDate ? value.toDate() : value;\r\n      const date = raw instanceof Date ? raw : new Date(raw);\r\n      return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleDateString(\"en-IN\");\r\n    }\r\n\r\n    function getPassoutYearFromTC(tcData = {}) {\r\n      const source = tcData.leavingDate || tcData.issueDate || tcData.generatedAt || new Date().toISOString();\r\n      const date = new Date(source);\r\n      if (!Number.isNaN(date.getTime())) return String(date.getFullYear());\r\n      const years = String(source).match(/\\b(20\\d{2}|19\\d{2})\\b/g);\r\n      return years?.length ? years[years.length - 1] : String(new Date().getFullYear());\r\n    }\r\n\r\n    async function loadStudentArchiveRecords(student = {}) {\r\n      const sid = student.studentId || student.id || \"\";\r\n      if (!sid) return { attendance: [], fees: [], reportCards: [] };\r\n      const [attendanceSnap, feesSnap, reportsSnap] = await Promise.all([\r\n        getDocs(query(collection(db, \"schools\", currentUser.uid, \"attendance\"), where(\"studentId\", \"==\", sid))),\r\n        getDocs(query(collection(db, \"schools\", currentUser.uid, \"fees\"), where(\"studentId\", \"==\", sid))),\r\n        getDocs(query(collection(db, \"schools\", currentUser.uid, \"reportCards\"), where(\"studentId\", \"==\", sid)))\r\n      ]);\r\n      return {\r\n        attendance: attendanceSnap.docs.map((d) => ({ id: d.id, ...d.data() })),\r\n        fees: feesSnap.docs.map((d) => ({ id: d.id, ...d.data() })),\r\n        reportCards: reportsSnap.docs.map((d) => ({ id: d.id, ...d.data() }))\r\n      };\r\n    }\r\n\r\n    async function archiveTCStudent(student, tcData, tcDocId) {\r\n      const archiveId = student.id || student.studentId;\r\n      const existingRecords = student.records || {};\r\n      const records = student._recordSource === \"archive\"\r\n        ? {\r\n            attendance: Array.isArray(existingRecords.attendance) ? existingRecords.attendance : [],\r\n            fees: Array.isArray(existingRecords.fees) ? existingRecords.fees : [],\r\n            reportCards: Array.isArray(existingRecords.reportCards) ? existingRecords.reportCards : []\r\n          }\r\n        : await loadStudentArchiveRecords(student);\r\n      await setDoc(doc(db, \"schools\", currentUser.uid, \"passedOutStudents\", archiveId), {\r\n        ...student,\r\n        _recordSource: null,\r\n        activeStudentDocId: student.id || \"\",\r\n        originalStudentDocId: student.id || \"\",\r\n        studentId: student.studentId || student.id || \"\",\r\n        passoutYear: student.passoutYear || getPassoutYearFromTC(tcData),\r\n        archiveReason: student.archiveReason || \"Transfer Certificate\",\r\n        archiveSource: \"transfer-certificate\",\r\n        status: student._recordSource === \"archive\" ? (student.status || \"Passed Out\") : \"TC Issued\",\r\n        finalClass: student.finalClass || student.class || \"\",\r\n        finalSection: student.finalSection || student.section || \"\",\r\n        tcIssued: true,\r\n        tcNumber: tcData.tcNumber || \"\",\r\n        tcCertificateDocId: tcDocId || \"\",\r\n        tcIssuedAt: tcData.generatedAt || new Date().toISOString(),\r\n        transferCertificate: { id: tcDocId || \"\", ...tcData },\r\n        records,\r\n        archivedAt: serverTimestamp(),\r\n        updatedAt: serverTimestamp()\r\n      }, { merge: true });\r\n      if (student._recordSource !== \"archive\") {\r\n        await deleteDoc(doc(db, \"schools\", currentUser.uid, \"students\", student.id));\r\n      }\r\n    }\r\n\r\n    function studentDisplayName(student) {\r\n      return student?.name || student?.studentName || \"N/A\";\r\n    }\r\n    function initials(name) {\r\n      return String(name || '?').split(/\\s+/).filter(Boolean).slice(0,2).map(w => w[0].toUpperCase()).join('') || '?';\r\n    }\r\n\r\n    function getStoredSchoolName() {\r\n      return window.SchoolBranding?.getSchoolName() || \"Schoolix School\";\r\n    }\r\n    function getDefaultSchoolAddress() {\r\n      return \"Affiliated to State Board\";\r\n    }\r\n\r\n    window.goBack = () => window.location.href = \"#/students.html\";\r\n\r\n    function showToast(message, type = 'success') {\r\n      const host = document.getElementById('toastHost');\r\n      const toast = document.createElement('div');\r\n      toast.className = `toast ${type}`;\r\n      const icon = type === 'error'\r\n        ? '<svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg>'\r\n        : '<svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg>';\r\n      toast.innerHTML = `${icon}<span>${esc(message)}</span>`;\r\n      host.appendChild(toast);\r\n      setTimeout(() => toast.remove(), 4000);\r\n    }\r\n\r\n    function showLoading(show, containerId) {\r\n      const container = document.getElementById(containerId);\r\n      if (!container) return;\r\n      if (show) container.innerHTML = '<div class=\"loading\"><div class=\"spinner\"></div><span>Loading...</span></div>';\r\n    }\r\n\r\n    window.switchTab = (tabName) => {\r\n      document.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));\r\n      document.querySelectorAll('.tab-content').forEach(content => content.classList.remove('active'));\r\n      document.querySelector(`[onclick=\"switchTab('${tabName}')\"]`).classList.add('active');\r\n      document.getElementById(tabName + 'Tab').classList.add('active');\r\n    };\r\n\r\n    window.showDeleteModal = (tcId, tcNumber) => {\r\n      tcToDelete = tcId;\r\n      document.getElementById('deleteMessage').textContent = `Are you sure you want to delete TC ${tcNumber}?`;\r\n      document.getElementById('deleteModal').classList.add('open');\r\n    };\r\n    window.closeDeleteModal = () => {\r\n      document.getElementById('deleteModal').classList.remove('open');\r\n      tcToDelete = null;\r\n    };\r\n    window.confirmDeleteTC = async () => {\r\n      if (!tcToDelete) return;\r\n      try {\r\n        const tcSnap = await getDoc(doc(db, \"schools\", currentUser.uid, \"transferCertificates\", tcToDelete));\r\n        const tcData = tcSnap.exists() ? tcSnap.data() : null;\r\n        await deleteDoc(doc(db, \"schools\", currentUser.uid, \"transferCertificates\", tcToDelete));\r\n        if (tcData?.studentDocId) {\r\n          await updateDoc(doc(db, \"schools\", currentUser.uid, \"students\", tcData.studentDocId), {\r\n            tcIssued: false, tcNumber: \"\", tcIssuedAt: null, tcCertificateDocId: null, updatedAt: serverTimestamp()\r\n          }).catch(() => {});\r\n        } else if (tcData?.studentId) {\r\n          const stSnap = await getDocs(query(collection(db, \"schools\", currentUser.uid, \"students\"), where(\"studentId\", \"==\", tcData.studentId)));\r\n          if (!stSnap.empty) {\r\n            await updateDoc(doc(db, \"schools\", currentUser.uid, \"students\", stSnap.docs[0].id), {\r\n              tcIssued: false, tcNumber: \"\", tcIssuedAt: null, tcCertificateDocId: null, updatedAt: serverTimestamp()\r\n            }).catch(() => {});\r\n          }\r\n        }\r\n        if (tcData?.archiveStudentDocId) {\r\n          await updateDoc(doc(db, \"schools\", currentUser.uid, \"passedOutStudents\", tcData.archiveStudentDocId), {\r\n            tcIssued: false,\r\n            tcNumber: \"\",\r\n            tcIssuedAt: null,\r\n            tcCertificateDocId: null,\r\n            transferCertificate: null,\r\n            status: \"Passed Out\",\r\n            updatedAt: serverTimestamp()\r\n          }).catch(() => {});\r\n        } else if (tcData?.studentId) {\r\n          const archivedSnap = await getDocs(query(collection(db, \"schools\", currentUser.uid, \"passedOutStudents\"), where(\"studentId\", \"==\", tcData.studentId)));\r\n          if (!archivedSnap.empty) {\r\n            await updateDoc(doc(db, \"schools\", currentUser.uid, \"passedOutStudents\", archivedSnap.docs[0].id), {\r\n              tcIssued: false,\r\n              tcNumber: \"\",\r\n              tcIssuedAt: null,\r\n              tcCertificateDocId: null,\r\n              transferCertificate: null,\r\n              status: \"Passed Out\",\r\n              updatedAt: serverTimestamp()\r\n            }).catch(() => {});\r\n          }\r\n        }\r\n        showToast('TC deleted. Student record unlocked.', 'success');\r\n        closeDeleteModal();\r\n        await loadIssuedTCs();\r\n        await loadStudents();\r\n      } catch (error) {\r\n        console.error(\"Error deleting TC:\", error);\r\n        showToast('Error deleting TC', 'error');\r\n      }\r\n    };\r\n\r\n    onAuthStateChanged(auth, async (user) => {\r\n      if (!user) { showToast('Please login first', 'error'); return window.location.href = \"#/index.html\"; }\r\n      currentUser = user;\r\n      try {\r\n        await Promise.all([loadStudents(), loadIssuedTCs()]);\r\n        switchTab('generate');\r\n      } catch (error) {\r\n        console.error('Error initializing:', error);\r\n        showToast('Error loading data: ' + error.message, 'error');\r\n      }\r\n    });\r\n\r\n    window.loadStudents = async () => {\r\n      if (!currentUser) { showToast('Please login first', 'error'); return; }\r\n      try {\r\n        showLoading(true, \"studentResult\");\r\n        const [studentSnap, archivedSnap] = await Promise.all([\r\n          getDocs(collection(db, \"schools\", currentUser.uid, \"students\")),\r\n          getDocs(collection(db, \"schools\", currentUser.uid, \"passedOutStudents\"))\r\n        ]);\r\n        allStudents = [];\r\n        studentSnap.forEach((d) => allStudents.push({ id: d.id, _recordSource: \"active\", ...d.data() }));\r\n        archivedSnap.forEach((d) => allStudents.push({ id: d.id, _recordSource: \"archive\", ...d.data() }));\r\n        populateClassFilter();\r\n        document.getElementById(\"studentResult\").innerHTML = emptySearchState();\r\n        showToast(`Loaded ${allStudents.length} students including passed out records.`, 'success');\r\n      } catch (error) {\r\n        console.error(\"Error loading students:\", error);\r\n        document.getElementById(\"studentResult\").innerHTML = `\r\n          <div class=\"error-state\">\r\n            <div class=\"icon-circle\"><svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg></div>\r\n            <h4>Error loading students</h4>\r\n            <p>${esc(error.message)}</p>\r\n            <button class=\"btn btn-primary btn-sm\" style=\"margin-top:12px;\" onclick=\"loadStudents()\">Retry</button>\r\n          </div>`;\r\n        showToast('Error loading students', 'error');\r\n      }\r\n    };\r\n\r\n    window.loadAllStudents = async () => { await loadStudents(); renderSearchResults(allStudents); };\r\n\r\n    window.searchStudent = () => {\r\n      const searchName = document.getElementById(\"searchName\")?.value?.trim().toLowerCase() || '';\r\n      const searchRoll = document.getElementById(\"searchRoll\")?.value?.trim() || '';\r\n      const searchClass = document.getElementById(\"searchClass\")?.value || '';\r\n      const searchStudentId = document.getElementById(\"searchStudentId\")?.value?.trim().toLowerCase() || '';\r\n      if (!searchName && !searchRoll && !searchClass && !searchStudentId) {\r\n        document.getElementById(\"studentResult\").innerHTML = emptySearchState();\r\n        return;\r\n      }\r\n      const found = allStudents.filter(s => {\r\n        const matchesName = !searchName || (studentDisplayName(s).toLowerCase().includes(searchName));\r\n        const matchesRoll = !searchRoll || (s.roll?.toString() === searchRoll);\r\n        const matchesClass = !searchClass || (s.class === searchClass) || (s.finalClass === searchClass);\r\n        const matchesId = !searchStudentId || (s.studentId?.toLowerCase().includes(searchStudentId));\r\n        return matchesName && matchesRoll && matchesClass && matchesId;\r\n      });\r\n      renderSearchResults(found);\r\n    };\r\n\r\n    function emptySearchState() {\r\n      return `<div class=\"empty-state\">\r\n        <div class=\"icon-circle\"><svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg></div>\r\n        <h4>Search for a student</h4>\r\n        <p>Enter Student Name, ID, Roll No, or Class to find students</p>\r\n      </div>`;\r\n    }\r\n\r\n    function renderSearchResults(students) {\r\n      const resultDiv = document.getElementById(\"studentResult\");\r\n      if (students.length === 0) {\r\n        resultDiv.innerHTML = `<div class=\"empty-state\">\r\n          <div class=\"icon-circle\"><svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"8\" y1=\"12\" x2=\"16\" y2=\"12\"/></svg></div>\r\n          <h4>No students found</h4><p>Try different search criteria or Show All Students</p></div>`;\r\n        return;\r\n      }\r\n      const html = '<div class=\"cards-list\">' + students.map(s => {\r\n        const issued = !!s.tcIssued;\r\n        const archived = s._recordSource === \"archive\";\r\n        const name = studentDisplayName(s);\r\n        return `\r\n        <div class=\"card-item ${issued ? 'tc-issued-card' : ''}\" data-student-id=\"${esc(s.id)}\" onclick=\"selectStudent('${esc(s.id)}')\">\r\n          <div class=\"card-head\">\r\n            <div class=\"card-title\">\r\n              <div class=\"avatar\">${esc(initials(name))}</div>\r\n              <span>${esc(name)}</span>\r\n            </div>\r\n            ${archived ? '<span class=\"pill pill-warning\">Passed Out</span>' : ''}\r\n            ${issued ? '<span class=\"pill pill-danger\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\"/><path d=\"M7 11V7a5 5 0 0 1 10 0v4\"/></svg>TC Issued</span>' : ''}\r\n          </div>\r\n          <div class=\"card-body-grid\">\r\n            <div><strong>Student ID:</strong>${esc(s.studentId || 'N/A')}</div>\r\n            <div><strong>Class:</strong>${esc(s.finalClass || s.class || '?')}${(s.finalSection || s.section) ? ' - ' + esc(s.finalSection || s.section) : ''}</div>\r\n            <div><strong>Roll No:</strong>${esc(s.roll || s.rollNo || '?')}</div>\r\n            ${archived ? `<div><strong>Passout Year:</strong>${esc(s.passoutYear || 'N/A')}</div>` : ''}\r\n            ${s.father ? `<div><strong>Father:</strong>${esc(s.father)}</div>` : ''}\r\n            ${s.mother ? `<div><strong>Mother:</strong>${esc(s.mother)}</div>` : ''}\r\n            ${s.phone ? `<div><strong>Phone:</strong>${esc(s.phone)}</div>` : ''}\r\n          </div>\r\n          ${issued ? '<div class=\"tc-note\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg>Transfer Certificate already issued. Cannot generate again.</div>' : ''}\r\n        </div>`;\r\n      }).join('') + '</div>';\r\n      resultDiv.innerHTML = html;\r\n    }\r\n\r\n    window.selectStudent = (id) => {\r\n      selectedStudent = allStudents.find(s => s.id === id);\r\n      if (!selectedStudent) { showToast('Student not found', 'error'); return; }\r\n      if (selectedStudent.tcIssued) { showToast('TC already issued for this student. Cannot generate again.', 'error'); return; }\r\n      document.querySelectorAll('.card-item').forEach(card => card.classList.remove('selected'));\r\n      const cardEl = document.querySelector(`.card-item[data-student-id=\"${id}\"]`);\r\n      if (cardEl) cardEl.classList.add('selected');\r\n      document.getElementById(\"selectedStudentName\").textContent = studentDisplayName(selectedStudent);\r\n      document.getElementById(\"tcFormSection\").style.display = \"block\";\r\n      populateTCForm();\r\n      document.getElementById(\"tcFormSection\").scrollIntoView({ behavior: 'smooth' });\r\n      showToast(`${studentDisplayName(selectedStudent)} selected. Fill TC details below.`, 'success');\r\n    };\r\n\r\n    function populateClassFilter() {\r\n      const classSet = new Set();\r\n      allStudents.forEach(s => {\r\n        if (s.class) classSet.add(s.class);\r\n        if (s.finalClass) classSet.add(s.finalClass);\r\n      });\r\n      const select = document.getElementById('searchClass');\r\n      select.innerHTML = '<option value=\"\">Select Class</option>';\r\n      Array.from(classSet).sort().forEach(c => { select.innerHTML += `<option value=\"${esc(c)}\">${esc(c)}</option>`; });\r\n    }\r\n\r\n    function populateTCForm() {\r\n      if (!selectedStudent) return;\r\n      const today = new Date().toISOString().split('T')[0];\r\n      const iso = (v) => v ? new Date(v).toISOString().split('T')[0] : '';\r\n      const set = (id, val) => { const el = document.getElementById(id); if (el) el.value = val ?? ''; };\r\n      const s = selectedStudent;\r\n      set(\"tcNumber\", `TC-${s.studentId || s.id || 'N/A'}-${Date.now().toString().slice(-6)}`);\r\n      set(\"bookNo\", \"\");\r\n      set(\"applicationDate\", today);\r\n      set(\"leavingDate\", today);\r\n      set(\"issueDate\", today);\r\n      set(\"placeOfIssue\", \"\");\r\n      // Parent / guardian\r\n      set(\"fatherName\", s.father || s.fatherName || '');\r\n      set(\"motherName\", s.mother || s.motherName || '');\r\n      set(\"guardianName\", s.guardian || s.guardianName || '');\r\n      set(\"nationality\", s.nationality || 'Indian');\r\n      set(\"religion\", s.religion || '');\r\n      set(\"category\", s.category || 'General');\r\n      // Student / admission\r\n      set(\"admissionNo\", s.admissionNo || s.studentId || '');\r\n      set(\"rollNo\", s.roll || s.rollNo || '');\r\n      set(\"aadhaarPen\", s.aadhaar || s.pen || '');\r\n      set(\"dob\", iso(s.dob));\r\n      set(\"dobWords\", \"\");\r\n      set(\"admissionDate\", iso(s.admissionDate));\r\n      set(\"admittedClass\", s.admittedClass || '');\r\n      const lastClass = s.finalClass || s.class || \"\";\r\n      const lastSection = s.finalSection || s.section || \"\";\r\n      set(\"lastClass\", `${lastClass}${lastSection ? ` (${lastSection})` : ''}`.trim());\r\n      set(\"section\", s.section || '');\r\n      set(\"medium\", s.medium || 'English');\r\n      // Academic\r\n      set(\"lastExamResult\", `Passed Class ${s.class || 'N/A'}`);\r\n      set(\"qualifiedPromotion\", \"Yes\");\r\n      set(\"promotedTo\", \"\");\r\n      set(\"failedRepeated\", \"No\");\r\n      set(\"subjects\", \"English, Hindi, Mathematics, Science, Social Science\");\r\n      set(\"coCurricular\", \"\");\r\n      set(\"nccScout\", \"No\");\r\n      set(\"workingDays\", \"220\");\r\n      set(\"daysPresent\", \"210\");\r\n      set(\"conduct\", \"Good\");\r\n      // Fees / remarks\r\n      set(\"feesPaidUpto\", \"Paid in Full\");\r\n      set(\"feeConcession\", \"Nil\");\r\n      set(\"identMark1\", \"\");\r\n      set(\"identMark2\", \"\");\r\n      set(\"remarks\", \"Character and Conduct Good\");\r\n      // School / signatories\r\n      set(\"schoolName\", getStoredSchoolName());\r\n      set(\"schoolAddress\", getDefaultSchoolAddress());\r\n      set(\"affiliationNo\", \"\");\r\n      set(\"udise\", \"\");\r\n      set(\"classTeacher\", s.classTeacher || 'Class Teacher');\r\n      set(\"clerk\", \"\");\r\n      set(\"principalName\", 'Principal');\r\n    }\r\n\r\n    window.showTCPREVIEW = () => {\r\n      if (!selectedStudent) { showToast('Please select a student first', 'error'); return; }\r\n      const data = getFormData();\r\n      if (!data.reason || !data.leavingDate || !data.tcNumber) {\r\n        showToast(\"Reason, leaving date and TC number are required.\", \"error\"); return;\r\n      }\r\n      tcPreviewData = { ...data, studentId: selectedStudent.studentId, studentName: studentDisplayName(selectedStudent) };\r\n      renderPreview();\r\n      document.getElementById(\"tcPreview\").style.display = \"block\";\r\n      document.getElementById(\"tcFormSection\").style.display = \"none\";\r\n      document.getElementById(\"tcPreview\").scrollIntoView({ behavior: 'smooth' });\r\n    };\r\n\r\n    function getFormData() {\r\n      const val = (id) => document.getElementById(id)?.value ?? '';\r\n      return {\r\n        reason: val(\"reason\"),\r\n        tcNumber: val(\"tcNumber\"),\r\n        bookNo: val(\"bookNo\"),\r\n        applicationDate: val(\"applicationDate\"),\r\n        leavingDate: val(\"leavingDate\"),\r\n        issueDate: val(\"issueDate\"),\r\n        placeOfIssue: val(\"placeOfIssue\"),\r\n        fatherName: val(\"fatherName\"),\r\n        motherName: val(\"motherName\"),\r\n        guardianName: val(\"guardianName\"),\r\n        nationality: val(\"nationality\"),\r\n        religion: val(\"religion\"),\r\n        category: val(\"category\"),\r\n        admissionNo: val(\"admissionNo\"),\r\n        rollNo: val(\"rollNo\"),\r\n        aadhaarPen: val(\"aadhaarPen\"),\r\n        dob: val(\"dob\"),\r\n        dobWords: val(\"dobWords\"),\r\n        admissionDate: val(\"admissionDate\"),\r\n        admittedClass: val(\"admittedClass\"),\r\n        lastClass: val(\"lastClass\"),\r\n        section: val(\"section\"),\r\n        medium: val(\"medium\"),\r\n        lastExamResult: val(\"lastExamResult\"),\r\n        qualifiedPromotion: val(\"qualifiedPromotion\"),\r\n        promotedTo: val(\"promotedTo\"),\r\n        failedRepeated: val(\"failedRepeated\"),\r\n        subjects: val(\"subjects\"),\r\n        coCurricular: val(\"coCurricular\"),\r\n        nccScout: val(\"nccScout\"),\r\n        workingDays: val(\"workingDays\"),\r\n        daysPresent: val(\"daysPresent\"),\r\n        conduct: val(\"conduct\"),\r\n        feesPaidUpto: val(\"feesPaidUpto\"),\r\n        feeConcession: val(\"feeConcession\"),\r\n        identMark1: val(\"identMark1\"),\r\n        identMark2: val(\"identMark2\"),\r\n        remarks: val(\"remarks\"),\r\n        schoolName: val(\"schoolName\"),\r\n        schoolAddress: val(\"schoolAddress\"),\r\n        affiliationNo: val(\"affiliationNo\"),\r\n        udise: val(\"udise\"),\r\n        classTeacher: val(\"classTeacher\"),\r\n        clerk: val(\"clerk\"),\r\n        principal: val(\"principalName\")\r\n      };\r\n    }\r\n\r\n    // Renders an inline-editable value span so every value can be edited in the preview\r\n    function ef(key, value, placeholder = '-') {\r\n      return `<span class=\"editable-field\" contenteditable=\"true\" data-key=\"${esc(key)}\" data-placeholder=\"${esc(placeholder)}\">${esc(value ?? '')}</span>`;\r\n    }\r\n\r\n    // Reads every edited value back out of the preview into a plain object\r\n    function collectEditedData() {\r\n      const previewContent = document.getElementById(\"previewContent\");\r\n      const out = {};\r\n      previewContent.querySelectorAll('[data-key]').forEach(node => {\r\n        out[node.dataset.key] = node.textContent.trim();\r\n      });\r\n      out.previewHtml = previewContent.innerHTML;\r\n      return out;\r\n    }\r\n\r\n    function renderPreview() {\r\n      const previewContent = document.getElementById(\"previewContent\");\r\n      const d = tcPreviewData;\r\n      const issueTxt = d.issueDate ? new Date(d.issueDate).toLocaleDateString('en-IN') : new Date().toLocaleDateString('en-IN');\r\n      previewContent.setAttribute('contenteditable', 'true');\r\n      previewContent.spellcheck = false;\r\n      previewContent.innerHTML = `\r\n        <h2>TRANSFER CERTIFICATE</h2>\r\n        <div class=\"school-name\">${ef('schoolName', d.schoolName || getStoredSchoolName(), 'School name')}</div>\r\n        <div class=\"school-addr\">${ef('schoolAddress', d.schoolAddress || getDefaultSchoolAddress(), 'School address')}\r\n          <div style=\"font-size:12px; color:#64748b; margin-top:4px;\">\r\n            Affiliation No: ${ef('affiliationNo', d.affiliationNo, '-')} &nbsp;|&nbsp; Reg./UDISE No: ${ef('udise', d.udise, '-')}\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"meta-row\">\r\n          <div><strong>Certificate No:</strong> ${ef('tcNumber', d.tcNumber, '-')}<br/>\r\n               <strong>Book No:</strong> ${ef('bookNo', d.bookNo, '-')}<br/>\r\n               <strong>Admission / Register No:</strong> ${ef('admissionNo', d.admissionNo, '-')}</div>\r\n          <div style=\"text-align:right;\"><strong>Date of Issue:</strong> ${ef('issueDateText', issueTxt, '-')}<br/>\r\n               <strong>Place:</strong> ${ef('placeOfIssue', d.placeOfIssue, '-')}</div>\r\n        </div>\r\n\r\n        <div class=\"tc-field\"><strong>1. Name of Pupil:</strong> ${ef('studentName', d.studentName)}</div>\r\n        <div class=\"tc-field\"><strong>2. Mother's Name:</strong> ${ef('motherName', d.motherName)}</div>\r\n        <div class=\"tc-field\"><strong>3. Father's Name:</strong> ${ef('fatherName', d.fatherName)}</div>\r\n        <div class=\"tc-field\"><strong>4. Guardian's Name:</strong> ${ef('guardianName', d.guardianName)}</div>\r\n        <div class=\"tc-field\"><strong>5. Nationality:</strong> ${ef('nationality', d.nationality || 'Indian')}</div>\r\n        <div class=\"tc-field\"><strong>6. Religion:</strong> ${ef('religion', d.religion)}</div>\r\n        <div class=\"tc-field\"><strong>7. Category (SC/ST/OBC/Gen):</strong> ${ef('category', d.category || 'General')}</div>\r\n        <div class=\"tc-field\"><strong>8. Aadhaar / PEN No:</strong> ${ef('aadhaarPen', d.aadhaarPen)}</div>\r\n        <div class=\"tc-field\"><strong>9. Date of Birth (in figures):</strong> ${ef('dob', safeDateText(d.dob))}</div>\r\n        <div class=\"tc-field\"><strong>10. Date of Birth (in words):</strong> ${ef('dobWords', d.dobWords)}</div>\r\n        <div class=\"tc-field\"><strong>11. Date of First Admission:</strong> ${ef('admissionDate', safeDateText(d.admissionDate))}</div>\r\n        <div class=\"tc-field\"><strong>12. Class in which Admitted:</strong> ${ef('admittedClass', d.admittedClass)}</div>\r\n        <div class=\"tc-field\"><strong>13. Class in which Last Studied:</strong> ${ef('lastClass', d.lastClass)}</div>\r\n        <div class=\"tc-field\"><strong>14. Section:</strong> ${ef('section', d.section)}</div>\r\n        <div class=\"tc-field\"><strong>15. Medium of Instruction:</strong> ${ef('medium', d.medium || 'English')}</div>\r\n        <div class=\"tc-field\"><strong>16. Roll No:</strong> ${ef('rollNo', d.rollNo)}</div>\r\n        <div class=\"tc-field\"><strong>17. Annual Exam Last Taken &amp; Result:</strong> ${ef('lastExamResult', d.lastExamResult)}</div>\r\n        <div class=\"tc-field\"><strong>18. Whether Qualified for Promotion:</strong> ${ef('qualifiedPromotion', d.qualifiedPromotion || 'Yes')}</div>\r\n        <div class=\"tc-field\"><strong>19. Promoted to Class:</strong> ${ef('promotedTo', d.promotedTo)}</div>\r\n        <div class=\"tc-field\"><strong>20. Whether Failed / Repeated:</strong> ${ef('failedRepeated', d.failedRepeated || 'No')}</div>\r\n        <div class=\"tc-field\"><strong>21. Subjects Studied:</strong> ${ef('subjects', d.subjects || 'English, Hindi, Mathematics, Science, Social Science')}</div>\r\n        <div class=\"tc-field\"><strong>22. Co-curricular Activities / Games:</strong> ${ef('coCurricular', d.coCurricular)}</div>\r\n        <div class=\"tc-field\"><strong>23. Whether NCC Cadet / Scout / Guide:</strong> ${ef('nccScout', d.nccScout || 'No')}</div>\r\n        <div class=\"tc-field\"><strong>24. Total No. of Working Days:</strong> ${ef('workingDays', d.workingDays || '220')}</div>\r\n        <div class=\"tc-field\"><strong>25. Total No. of Days Present:</strong> ${ef('daysPresent', d.daysPresent || '210')}</div>\r\n        <div class=\"tc-field\"><strong>26. School Dues Paid Upto:</strong> ${ef('feesPaidUpto', d.feesPaidUpto || 'Paid in Full')}</div>\r\n        <div class=\"tc-field\"><strong>27. Fee Concession (if any):</strong> ${ef('feeConcession', d.feeConcession || 'Nil')}</div>\r\n        <div class=\"tc-field\"><strong>28. General Conduct:</strong> ${ef('conduct', d.conduct || 'Good')}</div>\r\n        <div class=\"tc-field\"><strong>29. Date of Application for Certificate:</strong> ${ef('applicationDate', safeDateText(d.applicationDate))}</div>\r\n        <div class=\"tc-field\"><strong>30. Date of Leaving School / Struck Off:</strong> ${ef('leavingDate', safeDateText(d.leavingDate))}</div>\r\n        <div class=\"tc-field\"><strong>31. Reason for Leaving School:</strong> ${ef('reason', d.reason)}</div>\r\n        <div class=\"tc-field\"><strong>32. Identification Mark (i):</strong> ${ef('identMark1', d.identMark1)}</div>\r\n        <div class=\"tc-field\"><strong>33. Identification Mark (ii):</strong> ${ef('identMark2', d.identMark2)}</div>\r\n        <div class=\"tc-field\"><strong>34. Any Other Remarks:</strong> ${ef('remarks', d.remarks || 'Character and Conduct Good')}</div>\r\n\r\n        <div class=\"sig-row\">\r\n          <div class=\"sig-box\"><div class=\"sig-line\"></div><strong>Prepared / Clerk</strong><div>${ef('clerk', d.clerk)}</div></div>\r\n          <div class=\"sig-box\"><div class=\"sig-line\"></div><strong>Class Teacher</strong><div>${ef('classTeacher', d.classTeacher)}</div></div>\r\n          <div class=\"sig-box\"><div class=\"sig-line\"></div><strong>Principal / Head</strong><div>${ef('principal', d.principal)}</div></div>\r\n        </div>\r\n      `;\r\n    }\r\n\r\n    window.updatePreviewFromForm = () => {\r\n      if (!selectedStudent) return;\r\n      tcPreviewData = { ...getFormData(), studentId: selectedStudent.studentId, studentName: studentDisplayName(selectedStudent) };\r\n      renderPreview();\r\n      showToast('Preview updated from form.', 'success');\r\n    };\r\n\r\n    window.backToForm = () => {\r\n      document.getElementById(\"tcPreview\").style.display = \"none\";\r\n      document.getElementById(\"tcFormSection\").style.display = \"block\";\r\n    };\r\n\r\n    window.finalizeTC = async () => {\r\n      if (!selectedStudent) { showToast('Please select a student first', 'error'); return; }\r\n      if (selectedStudent.tcIssued) { showToast('This student already has a TC issued.', 'error'); return; }\r\n      try {\r\n        const edited = collectEditedData();\r\n        const finalData = {\r\n          ...tcPreviewData,\r\n          ...edited,\r\n          studentId: selectedStudent.studentId,\r\n          studentName: studentDisplayName(selectedStudent),\r\n          class: selectedStudent.finalClass || selectedStudent.class || 'N/A',\r\n          section: selectedStudent.finalSection || selectedStudent.section || '',\r\n          roll: selectedStudent.roll || 'N/A',\r\n          generatedBy: currentUser.uid,\r\n          generatedAt: new Date().toISOString(),\r\n          studentDocId: selectedStudent._recordSource === \"archive\" ? \"\" : selectedStudent.id,\r\n          archiveStudentDocId: selectedStudent._recordSource === \"archive\" ? selectedStudent.id : \"\"\r\n        };\r\n        if (!finalData.leavingDate) { showToast('Please set leaving date', 'error'); return; }\r\n        if (!finalData.tcNumber) { showToast('Please enter TC number', 'error'); return; }\r\n        const duplicateSnap = await getDocs(query(\r\n          collection(db, \"schools\", currentUser.uid, \"transferCertificates\"),\r\n          where(\"studentId\", \"==\", selectedStudent.studentId)\r\n        ));\r\n        if (!duplicateSnap.empty) {\r\n          showToast(\"TC already exists for this student. Refreshing records.\", \"error\");\r\n          await loadIssuedTCs(); return;\r\n        }\r\n        const docRef = await addDoc(collection(db, \"schools\", currentUser.uid, \"transferCertificates\"), finalData);\r\n        await archiveTCStudent(selectedStudent, finalData, docRef.id);\r\n        if (selectedStudent._recordSource === \"archive\") {\r\n          allStudents = allStudents.map((s) => s.id === selectedStudent.id ? {\r\n            ...s,\r\n            tcIssued: true,\r\n            tcNumber: finalData.tcNumber || \"\",\r\n            tcCertificateDocId: docRef.id,\r\n            transferCertificate: { id: docRef.id, ...finalData },\r\n            status: s.status || \"Passed Out\"\r\n          } : s);\r\n        } else {\r\n          allStudents = allStudents.filter((s) => s.id !== selectedStudent.id);\r\n        }\r\n        selectedStudent = null;\r\n        showToast(`TC ${finalData.tcNumber} saved and uploaded to student dashboard.`, 'success');\r\n        await loadIssuedTCs();\r\n        generateAndPrintTC(finalData);\r\n        resetForm();\r\n        switchTab('issued');\r\n      } catch (error) {\r\n        console.error(\"Error saving TC:\", error);\r\n        showToast('Error saving TC: ' + error.message, 'error');\r\n      }\r\n    };\r\n\r\n    function resetForm() {\r\n      document.getElementById(\"tcPreview\").style.display = \"none\";\r\n      document.getElementById(\"tcFormSection\").style.display = \"none\";\r\n      selectedStudent = null;\r\n      tcPreviewData = {};\r\n      document.getElementById(\"selectedStudentName\").textContent = '';\r\n      document.querySelectorAll('#tcFormSection input, #tcFormSection select, #tcFormSection textarea').forEach(el => { el.value = ''; });\r\n      ['searchName', 'searchRoll', 'searchClass', 'searchStudentId'].forEach(id => {\r\n        const el = document.getElementById(id); if (el) el.value = '';\r\n      });\r\n      document.getElementById(\"studentResult\").innerHTML = emptySearchState();\r\n    }\r\n\r\n    async function loadIssuedTCs() {\r\n      try {\r\n        showLoading(true, \"issuedTCsList\");\r\n        const tcSnap = await getDocs(collection(db, \"schools\", currentUser.uid, \"transferCertificates\"));\r\n        allTCs = tcSnap.docs.map(d => ({ id: d.id, ...d.data() })).sort((a,b) => new Date(b.generatedAt || 0) - new Date(a.generatedAt || 0));\r\n        populateTCClassFilter();\r\n        renderIssuedTCs(allTCs);\r\n      } catch (error) {\r\n        console.error(\"Error loading TCs:\", error);\r\n        showToast('Error loading TCs', 'error');\r\n      }\r\n    }\r\n\r\n    window.searchIssuedTCs = () => {\r\n      const searchStudent = document.getElementById(\"tcSearchStudent\")?.value?.trim().toLowerCase() || '';\r\n      const searchNumber = document.getElementById(\"tcSearchNumber\")?.value?.trim().toLowerCase() || '';\r\n      const searchClass = document.getElementById(\"tcSearchClass\")?.value || '';\r\n      const searchDate = document.getElementById(\"tcSearchDate\")?.value || '';\r\n      let filtered = allTCs.filter(tc => {\r\n        if (searchStudent && !tc.studentName?.toLowerCase().includes(searchStudent) && !tc.studentId?.toLowerCase().includes(searchStudent)) return false;\r\n        if (searchNumber && !tc.tcNumber?.toLowerCase().includes(searchNumber)) return false;\r\n        if (searchClass && tc.class !== searchClass) return false;\r\n        if (searchDate) {\r\n          const generated = new Date(tc.generatedAt || 0);\r\n          if (Number.isNaN(generated.getTime()) || generated.toISOString().split('T')[0] !== searchDate) return false;\r\n        }\r\n        return true;\r\n      });\r\n      renderIssuedTCs(filtered);\r\n    };\r\n\r\n    function renderIssuedTCs(tcs) {\r\n      const resultDiv = document.getElementById(\"issuedTCsList\");\r\n      if (tcs.length === 0) {\r\n        resultDiv.innerHTML = `<div class=\"empty-state\">\r\n          <div class=\"icon-circle\"><svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg></div>\r\n          <h4>No TCs found</h4><p>No transfer certificates match your search criteria</p></div>`;\r\n        return;\r\n      }\r\n      const html = '<div class=\"cards-list\">' + tcs.map(tc => `\r\n        <div class=\"card-item\" style=\"cursor:default; border-left: 4px solid var(--success);\">\r\n          <div class=\"card-head\">\r\n            <div class=\"card-title\">\r\n              <div class=\"avatar\" style=\"background: var(--success-50); color: var(--success);\">\r\n                <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg>\r\n              </div>\r\n              <span>TC: ${esc(tc.tcNumber || 'N/A')}</span>\r\n            </div>\r\n            <span class=\"pill pill-success\">Issued</span>\r\n          </div>\r\n          <div class=\"card-body-grid\">\r\n            <div><strong>Student:</strong>${esc(tc.studentName || 'N/A')}</div>\r\n            <div><strong>ID:</strong>${esc(tc.studentId || 'N/A')}</div>\r\n            <div><strong>Class:</strong>${esc(tc.class || 'N/A')}${tc.section ? ` (${esc(tc.section)})` : ''}</div>\r\n            <div><strong>Issued:</strong>${esc(safeDateText(tc.generatedAt))}</div>\r\n            <div style=\"grid-column: 1 / -1;\"><strong>Reason:</strong>${esc(tc.reason || '')}</div>\r\n          </div>\r\n          <div class=\"toolbar\" style=\"margin-top: 14px;\">\r\n            <button class=\"btn btn-primary btn-sm\" onclick=\"printTC('${esc(tc.id)}')\">\r\n              <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 6 2 18 2 18 9\"/><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"/><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"/></svg>\r\n              Print TC\r\n            </button>\r\n            <button class=\"btn btn-secondary btn-sm\" onclick=\"downloadTCPDF('${esc(tc.id)}')\">\r\n              <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\r\n              Download PDF\r\n            </button>\r\n          </div>\r\n        </div>\r\n      `).join('') + '</div>';\r\n      resultDiv.innerHTML = html;\r\n    }\r\n\r\n    function populateTCClassFilter() {\r\n      const classSet = new Set();\r\n      allTCs.forEach(tc => { if (tc.class) classSet.add(tc.class); });\r\n      const select = document.getElementById('tcSearchClass');\r\n      select.innerHTML = '<option value=\"\">All Classes</option>';\r\n      Array.from(classSet).sort().forEach(c => { select.innerHTML += `<option value=\"${esc(c)}\">${esc(c)}</option>`; });\r\n    }\r\n\r\n    function generateAndPrintTC(tcData) {\r\n      const htmlContent = generateTCHTML(tcData);\r\n      const printWindow = window.open('', '_blank');\r\n      if (!printWindow) { showToast(\"Popup blocked. Allow popups to print TC.\", \"error\"); return; }\r\n      printWindow.document.write(htmlContent);\r\n      printWindow.document.close();\r\n      setTimeout(() => printWindow.print(), 500);\r\n    }\r\n\r\n    function tcPrintStyles() {\r\n      return `\r\n        @page { size: A4; margin: 16mm; }\r\n        body { font-family: 'Times New Roman', Georgia, serif; color: #111; padding: 0; margin: 0; }\r\n        .tc-container { max-width: 800px; margin: 0 auto; padding: 30px; border: 2px solid #333; }\r\n        h2 { text-align: center; font-size: 26px; letter-spacing: 4px; margin: 0 0 8px; }\r\n        .school-name { text-align: center; font-size: 20px; font-weight: bold; }\r\n        .school-addr { text-align: center; font-size: 14px; color: #444; padding-bottom: 14px; margin-bottom: 20px; border-bottom: 2px double #333; }\r\n        .meta-row { display: flex; justify-content: space-between; margin-bottom: 22px; font-size: 14px; gap: 20px; }\r\n        .tc-field { font-size: 14.5px; margin: 8px 0; }\r\n        .tc-field strong { display: inline-block; min-width: 300px; }\r\n        .sig-row { display: flex; justify-content: space-between; margin-top: 64px; gap: 24px; }\r\n        .sig-box { text-align: center; flex: 1; }\r\n        .sig-line { border-top: 1.5px solid #333; margin-bottom: 6px; height: 40px; }\r\n        /* Neutralise the on-screen editable styling for a clean printout */\r\n        .editable-field { border: none !important; background: transparent !important; padding: 0 !important; min-width: 0 !important; box-shadow: none !important; font: inherit !important; }\r\n        [contenteditable] { outline: none; }\r\n        @media print { body { margin: 0; padding: 0; } .tc-container { border: none; } }\r\n      `;\r\n    }\r\n\r\n    function generateTCHTML(tcData) {\r\n      // Prefer the exact certificate the user edited inline in the preview\r\n      const body = tcData.previewHtml\r\n        ? tcData.previewHtml\r\n        : fallbackTCBody(tcData);\r\n      return `<!DOCTYPE html><html><head>\r\n<meta charset=\"UTF-8\">\r\n        <title>Transfer Certificate - ${esc(tcData.studentName || '')}</title>\r\n        <style>${tcPrintStyles()}</style>\r\n</head><body><div class=\"tc-container\">${body}</div></body></html>`;\r\n    }\r\n\r\n    // Used only when no inline-edited HTML was stored (older records)\r\n    function fallbackTCBody(t) {\r\n      const row = (n, label, value) => `<div class=\"tc-field\"><strong>${n}. ${label}:</strong> ${esc(value ?? '')}</div>`;\r\n      return `\r\n        <h2>TRANSFER CERTIFICATE</h2>\r\n        <div class=\"school-name\">${esc(t.schoolName || getStoredSchoolName())}</div>\r\n        <div class=\"school-addr\">${esc(t.schoolAddress || getDefaultSchoolAddress())}\r\n          <div style=\"font-size:12px;color:#555;margin-top:4px;\">Affiliation No: ${esc(t.affiliationNo || '-')} | Reg./UDISE No: ${esc(t.udise || '-')}</div>\r\n        </div>\r\n        <div class=\"meta-row\">\r\n          <div><strong>Certificate No:</strong> ${esc(t.tcNumber || '')}<br/><strong>Book No:</strong> ${esc(t.bookNo || '-')}<br/><strong>Admission / Register No:</strong> ${esc(t.admissionNo || t.rollNo || '')}</div>\r\n          <div style=\"text-align:right;\"><strong>Date of Issue:</strong> ${esc(safeDateText(t.issueDate || t.generatedAt))}<br/><strong>Place:</strong> ${esc(t.placeOfIssue || '-')}</div>\r\n        </div>\r\n        ${row(1, \"Name of Pupil\", t.studentName)}\r\n        ${row(2, \"Mother's Name\", t.motherName)}\r\n        ${row(3, \"Father's Name\", t.fatherName)}\r\n        ${row(4, \"Guardian's Name\", t.guardianName)}\r\n        ${row(5, \"Nationality\", t.nationality || 'Indian')}\r\n        ${row(6, \"Religion\", t.religion)}\r\n        ${row(7, \"Category (SC/ST/OBC/Gen)\", t.category || 'General')}\r\n        ${row(8, \"Aadhaar / PEN No\", t.aadhaarPen)}\r\n        ${row(9, \"Date of Birth (in figures)\", safeDateText(t.dob))}\r\n        ${row(10, \"Date of Birth (in words)\", t.dobWords)}\r\n        ${row(11, \"Date of First Admission\", safeDateText(t.admissionDate))}\r\n        ${row(12, \"Class in which Admitted\", t.admittedClass)}\r\n        ${row(13, \"Class in which Last Studied\", t.lastClass)}\r\n        ${row(14, \"Section\", t.section)}\r\n        ${row(15, \"Medium of Instruction\", t.medium || 'English')}\r\n        ${row(16, \"Roll No\", t.rollNo)}\r\n        ${row(17, \"Annual Exam Last Taken & Result\", t.lastExamResult)}\r\n        ${row(18, \"Whether Qualified for Promotion\", t.qualifiedPromotion || 'Yes')}\r\n        ${row(19, \"Promoted to Class\", t.promotedTo)}\r\n        ${row(20, \"Whether Failed / Repeated\", t.failedRepeated || 'No')}\r\n        ${row(21, \"Subjects Studied\", t.subjects || 'English, Hindi, Mathematics, Science, Social Science')}\r\n        ${row(22, \"Co-curricular Activities / Games\", t.coCurricular)}\r\n        ${row(23, \"Whether NCC Cadet / Scout / Guide\", t.nccScout || 'No')}\r\n        ${row(24, \"Total No. of Working Days\", t.workingDays || '220')}\r\n        ${row(25, \"Total No. of Days Present\", t.daysPresent || '210')}\r\n        ${row(26, \"School Dues Paid Upto\", t.feesPaidUpto || 'Paid in Full')}\r\n        ${row(27, \"Fee Concession (if any)\", t.feeConcession || 'Nil')}\r\n        ${row(28, \"General Conduct\", t.conduct || 'Good')}\r\n        ${row(29, \"Date of Application for Certificate\", safeDateText(t.applicationDate))}\r\n        ${row(30, \"Date of Leaving School / Struck Off\", safeDateText(t.leavingDate))}\r\n        ${row(31, \"Reason for Leaving School\", t.reason)}\r\n        ${row(32, \"Identification Mark (i)\", t.identMark1)}\r\n        ${row(33, \"Identification Mark (ii)\", t.identMark2)}\r\n        ${row(34, \"Any Other Remarks\", t.remarks || 'Character and Conduct Good')}\r\n        <div class=\"sig-row\">\r\n          <div class=\"sig-box\"><div class=\"sig-line\"></div><strong>Prepared / Clerk</strong><div>${esc(t.clerk || '')}</div></div>\r\n          <div class=\"sig-box\"><div class=\"sig-line\"></div><strong>Class Teacher</strong><div>${esc(t.classTeacher || 'Class Teacher')}</div></div>\r\n          <div class=\"sig-box\"><div class=\"sig-line\"></div><strong>Principal / Head</strong><div>${esc(t.principal || 'Principal')}</div></div>\r\n        </div>`;\r\n    }\r\n\r\n    window.printTC = (tcId) => { const tc = allTCs.find(t => t.id === tcId); if (tc) generateAndPrintTC(tc); };\r\n    window.downloadTCPDF = (tcId) => { const tc = allTCs.find(t => t.id === tcId); if (tc) generateAndPrintTC(tc); };\r\n\r\n    document.addEventListener('DOMContentLoaded', () => {\r\n      document.getElementById('confirmDelete')?.addEventListener('click', window.confirmDeleteTC);\r\n    });\r\n    document.getElementById('confirmDelete')?.addEventListener('click', window.confirmDeleteTC);\r\n  "},{"attributes":{"type":"module","src":"access-control.js"},"text":""},{"attributes":{"src":"schoolix-polish.js"},"text":""},{"attributes":{"src":"admin-shell.js?v=navbar-20260721"},"text":""}]};
